INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('1-1-comprendre-la-logique-toutes-les', 'module-1', 1, 'Vers quoi mènent TOUTES les routes d''immigration, au départ ?', 'Un titre de séjour (Aufenthaltstitel)', 'Un contrat de travail', 'Un visa touristique', 'La nationalité allemande directement', 0, 'Quelle que soit la porte, elle mène d''abord au même document légal : le titre de séjour.'),
  ('1-1-comprendre-la-logique-toutes-les', 'module-1', 2, 'Selon la métaphore du bâtiment, que peux-tu faire une fois « entré » ?', 'Rien, ton statut est figé à vie', 'Évoluer / changer de statut (ex : passer d''étudiant à travailleur)', 'Repartir et recommencer une autre porte', 'Obtenir immédiatement la nationalité', 1, 'Une fois à l''intérieur, tu peux te déplacer d''un statut à l''autre.'),
  ('1-1-comprendre-la-logique-toutes-les', 'module-1', 3, 'Quelle stratégie de choix de porte est recommandée ?', 'La porte que tout le monde prend', 'La porte la plus prestigieuse', 'La porte la plus FACILE à franchir pour toi maintenant', 'La porte la plus connue', 2, '« Entre par la porte la plus facile pour toi — pas la plus prestigieuse. »'),
  ('1-1-comprendre-la-logique-toutes-les', 'module-1', 4, 'Au bout du chemin, pour la plupart des routes, qu''y a-t-il ?', 'Un retour obligatoire au pays', 'Un nouveau visa à redemander', 'Un simple renouvellement annuel', 'La résidence permanente, puis éventuellement la nationalité', 3, 'La récompense est la même : résidence permanente puis nationalité.'),
  ('1-1-comprendre-la-logique-toutes-les', 'module-1', 5, 'Quel est le vrai but, selon la leçon ?', 'ENTRER (peu importe la porte)', 'Choisir la route la plus rapide à tout prix', 'Éviter de payer des frais', 'Impressionner l''administration', 0, '« Ton but, ce n''est pas d''impressionner qui que ce soit. C''est d''ENTRER. »')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('1-2-les-voies-principales-travail-qualifie', 'module-1', 1, 'Qu''est-ce que l''Ausbildung ?', 'Un stage non rémunéré', 'Un diplôme universitaire allemand', 'Une formation professionnelle payée en entreprise (l''entreprise te paie)', 'Un visa touristique de formation', 2, 'Tu apprends un métier sur le terrain ET l''entreprise te paie dès le 1er mois, zéro frais de scolarité.'),
  ('1-2-les-voies-principales-travail-qualifie', 'module-1', 2, 'Quel est l''avantage des études en Allemagne après l''obtention du diplôme ?', 'Un emploi garanti', 'Le remboursement des frais', 'La nationalité automatique', 'Un visa de 18 mois pour chercher un emploi sur place', 3, 'Université quasi gratuite + visa 18 mois post-diplôme pour chercher un emploi.'),
  ('1-2-les-voies-principales-travail-qualifie', 'module-1', 3, 'Quelle voie est la plus rapide vers la résidence permanente (~2 ans) ?', 'La Blue Card (travail qualifié)', 'Le regroupement familial', 'L''Ausbildung', 'Les études', 0, 'La Carte Bleue européenne : l''autoroute pour les diplômés du supérieur.'),
  ('1-2-les-voies-principales-travail-qualifie', 'module-1', 4, 'Pour la voie Santé, quelle est l''étape clé ?', 'Le compte bloqué', 'La reconnaissance du diplôme (Anerkennung)', 'Le niveau C1 obligatoire', 'Un contrat avant le visa', 1, 'L''Anerkennung est l''étape centrale de la voie santé.'),
  ('1-2-les-voies-principales-travail-qualifie', 'module-1', 5, 'L''Ausbildung est idéale pour quel profil ?', 'Uniquement ceux qui ont déjà un employeur', 'Diplômé bac+5 avec expérience', 'Niveau bac (ou proche), prêt à apprendre un métier, sans diplôme universitaire requis', 'Uniquement les médecins', 2, 'Accessible, et mène à la résidence permanente après la formation.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('1-3-les-voies-familiales-regroupement', 'module-1', 1, 'Sur quoi repose le regroupement familial ?', 'Un lien familial proche avec une personne vivant légalement en Allemagne', 'Un contrat de travail', 'Un niveau C1', 'Un diplôme reconnu', 0, 'Lien familial prouvé + une personne déjà installée légalement.'),
  ('1-3-les-voies-familiales-regroupement', 'module-1', 2, 'Quel double avantage offrent souvent les voies familiales ?', 'Gratuité totale + nationalité immédiate', 'Droit de travailler dès l''arrivée + niveau d''allemand exigé plus bas', 'Pas de visa nécessaire', 'Un logement fourni par l''État', 1, 'Travail immédiat + allemand de base (souvent A2).'),
  ('1-3-les-voies-familiales-regroupement', 'module-1', 3, 'Quel niveau d''allemand est souvent demandé pour le visa conjoint ?', 'C1', 'B2', 'A2', 'Aucun', 2, 'Un niveau de base, souvent A2.'),
  ('1-3-les-voies-familiales-regroupement', 'module-1', 4, 'Que doit prouver le conjoint déjà installé en Allemagne ?', 'La nationalité allemande', '5 ans de résidence', 'Un diplôme allemand', 'Un logement suffisant et des revenus', 3, 'Mariage légal reconnu + logement suffisant + revenus du conjoint.'),
  ('1-3-les-voies-familiales-regroupement', 'module-1', 5, 'Pourquoi explorer la voie familiale en priorité si on a de la famille proche là-bas ?', 'C''est souvent une voie beaucoup plus directe que les routes longues et compliquées', 'Elle donne la nationalité', 'Elle évite l''apprentissage de l''allemand', 'Elle est gratuite', 0, 'Beaucoup se lancent dans des routes longues alors qu''une porte directe leur tendait les bras.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('1-4-les-voies-tremplin', 'module-1', 1, 'Qu''est-ce qu''une voie « tremplin » ?', 'Un visa touristique', 'Une destination finale stable', 'Une voie qui te fait ENTRER, puis depuis laquelle tu rebondis vers une route stable', 'Une voie réservée aux diplômés', 2, 'Utile quand tu n''as pas encore d''offre ou de contrat en main.'),
  ('1-4-les-voies-tremplin', 'module-1', 2, 'Quelle est la particularité UNIQUE de la Chancenkarte (carte opportunité) ?', 'Elle est gratuite', 'Elle ne demande aucun diplôme', 'Elle donne la nationalité', 'C''est la seule qui ne demande PAS de contrat de travail signé avant de partir', 3, 'Système à points ; tu viens 1 an chercher un emploi sur place (travail partiel autorisé).'),
  ('1-4-les-voies-tremplin', 'module-1', 3, 'Sur quoi fonctionne la Chancenkarte ?', 'Un système à points (qualification, langue, expérience, âge)', 'L''ancienneté', 'Le pays d''origine', 'Le tirage au sort', 0, 'Si tu atteins le minimum de points, tu obtiens le droit de venir chercher un emploi sur place.'),
  ('1-4-les-voies-tremplin', 'module-1', 4, 'Le bénévolat (FSJ / BFD) est-il un chemin direct vers la résidence permanente ?', 'Oui, c''est la voie la plus rapide', 'Non — c''est un tremplin, pas une destination', 'Oui, après 6 mois', 'Oui, si l''allemand est bon', 1, 'Excellent pour mettre un pied + améliorer l''allemand, mais ce n''est PAS un chemin direct vers la résidence.'),
  ('1-4-les-voies-tremplin', 'module-1', 5, 'En quoi consiste l''au pair ?', 'Un programme de recherche', 'Un emploi qualifié payé au tarif plein', 'Être logé/nourri par une famille allemande, garder leurs enfants, en immersion (surtout pour les jeunes)', 'Une formation universitaire', 2, 'Immersion + progrès en allemand, puis bascule possible vers études ou formation.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('1-5-les-voies-speciales-asile', 'module-1', 1, 'La régulation des Balkans occidentaux (Westbalkanregelung) s''applique-t-elle aux Algériens ?', 'Non — réservée exclusivement à 6 pays des Balkans (l''Algérie n''en fait pas partie)', 'Oui, avec un diplôme', 'Oui, depuis 2024', 'Oui, sans condition', 0, 'Albanie, Bosnie, Kosovo, Monténégro, Macédoine du Nord, Serbie uniquement.'),
  ('1-5-les-voies-speciales-asile', 'module-1', 2, 'Si quelqu''un te propose de partir « par la régulation des Balkans », c''est…', 'Une excellente opportunité', 'Soit une erreur, soit une arnaque (cette porte n''est pas ouverte aux Algériens)', 'La voie la plus rapide', 'Réservé aux diplômés', 1, 'À fuir : ce n''est pas pour les Algériens.'),
  ('1-5-les-voies-speciales-asile', 'module-1', 3, 'L''asile est-il une voie d''immigration de travail ?', 'Oui, pour les jeunes', 'Oui, c''est un raccourci efficace', 'Non — c''est un dispositif de protection ; le détourner peut compromettre durablement tes voies légales', 'Oui, si on a un emploi', 2, 'L''asile protège ceux qui fuient une persécution ; ce n''est pas une voie économique.'),
  ('1-5-les-voies-speciales-asile', 'module-1', 4, 'Quel cas particulier RÉEL peut concerner un profil entrepreneur ?', 'La Westbalkanregelung', 'L''au pair', 'L''asile', 'La création d''entreprise / le travail indépendant (titre de séjour dédié)', 3, 'Exigeant (vrai plan, intérêt économique), mais une porte réelle.'),
  ('1-5-les-voies-speciales-asile', 'module-1', 5, 'Pour un chercheur ou un doctorant, qu''existe-t-il ?', 'Des voies dédiées, souvent plus rapides et accompagnées par les universités/instituts', 'Uniquement l''asile', 'Uniquement la Blue Card', 'Rien de spécifique', 0, 'Voies recherche/doctorat dédiées et bien accompagnées.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('1-6-le-test-quelle-voie-est-faite-pour-ta-situation', 'module-1', 1, 'Quelle est la 1re question du test pour trouver ta route ?', 'As-tu un diplôme ?', 'As-tu de l''argent ?', 'As-tu un conjoint, un parent ou un enfant légalement installé en Allemagne ?', 'Parles-tu allemand ?', 2, 'Si oui, explore la voie familiale en priorité (la plus directe).'),
  ('1-6-le-test-quelle-voie-est-faite-pour-ta-situation', 'module-1', 2, 'Tu as un diplôme reconnu + de l''expérience dans la santé. Ta route ?', 'Le bénévolat', 'L''asile', 'L''au pair', 'La voie santé, avec la reconnaissance du diplôme au centre', 3, 'Diplôme + santé → voie santé (Anerkennung au centre).'),
  ('1-6-le-test-quelle-voie-est-faite-pour-ta-situation', 'module-1', 3, 'Tu as un diplôme en IT / ingénierie / sciences. Vers quoi viser ?', 'Le travail qualifié et la Blue Card (ton autoroute)', 'La voie familiale', 'Le bénévolat', 'L''Ausbildung', 0, 'Profils du supérieur techniques/scientifiques → Blue Card.'),
  ('1-6-le-test-quelle-voie-est-faite-pour-ta-situation', 'module-1', 4, 'Tu as le niveau bac mais pas de diplôme supérieur. Tes options ?', 'Uniquement l''asile', 'L''Ausbildung (payé tout de suite) ou les études (université quasi gratuite)', 'Uniquement la Blue Card', 'Uniquement la voie familiale', 1, 'Gagner sa vie maintenant (Ausbildung) ou investir dans un diplôme (études).'),
  ('1-6-le-test-quelle-voie-est-faite-pour-ta-situation', 'module-1', 5, 'Si deux routes te conviennent, laquelle choisir ?', 'La moins chère seulement', 'La plus prestigieuse', 'Celle qui te fait ENTRER le plus vite et le plus sûrement', 'La plus longue mais la plus sûre', 2, 'Une fois à l''intérieur, tu pourras évoluer (rappel de la leçon 1.1).')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('1-7-l-erreur-de-choisir-la-mauvaise-porte', 'module-1', 1, 'Quelle est l''erreur n°1 (la plus chère) du parcours ?', 'Choisir sa route avec le cœur / l''ego au lieu de sa situation réelle', 'Oublier de payer les frais', 'Apprendre le mauvais dialecte', 'Une faute dans la traduction d''un document', 0, 'Une erreur de stratégie qui peut faire perdre 2 à 3 ans.'),
  ('1-7-l-erreur-de-choisir-la-mauvaise-porte', 'module-1', 2, 'Sur quels 3 critères comparer froidement ses options ?', 'Prestige, popularité, difficulté', 'Délai, Coût, Probabilité de réussite avec ton profil', 'Langue, ville, climat', 'Salaire, logement, transport', 1, 'Compare toujours délai / coût / probabilité, sans émotion.'),
  ('1-7-l-erreur-de-choisir-la-mauvaise-porte', 'module-1', 3, 'Concernant le COÛT, quelle différence est soulignée ?', 'Les deux coûtent un compte bloqué', 'Les études te paient, l''Ausbildung coûte cher', 'L''Ausbildung te paie, alors que les études te coûtent un compte bloqué', 'Les deux sont gratuites', 2, 'Ce n''est pas un détail dans le calcul du coût.'),
  ('1-7-l-erreur-de-choisir-la-mauvaise-porte', 'module-1', 4, 'C''est quoi « la bonne route » ?', 'La plus prestigieuse', 'Celle que ton entourage recommande', 'La plus belle sur le papier', 'Celle qui maximise tes chances d''entrer, au moindre coût, dans le délai le plus court', 3, 'Une fois entré, le reste s''ouvre.'),
  ('1-7-l-erreur-de-choisir-la-mauvaise-porte', 'module-1', 5, 'Que faire de la phrase « Ma route, c''est ___ » écrite à la leçon 1.6 ?', 'La passer au filtre des 3 critères (délai/coût/probabilité) pour la valider', 'La changer chaque semaine', 'Attendre 6 mois avant de décider', 'L''oublier', 0, 'Si elle tient le filtre, la route est validée ; sinon, réajuster maintenant (pas dans 6 mois).')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('2-1-diplomes-ce-qui-compte-ce-qui-ne', 'module-2', 1, 'Selon la leçon, comment l''Allemagne envisage-t-elle principalement un diplôme étranger ?', 'Comme une condition obligatoire pour tout emploi', 'Comme une preuve de prestige académique', 'Comme une preuve que tu peux faire un travail précis', 'Comme un simple trophée à afficher', 2, 'La leçon explique que l''Allemagne ne regarde pas le diplôme comme un trophée, mais de manière pragmatique : comme une preuve que tu peux faire un travail précis.'),
  ('2-1-diplomes-ce-qui-compte-ce-qui-ne', 'module-2', 2, 'Quelle est la véritable question à se poser en Allemagne concernant son diplôme ?', 'Mon diplôme provient-il d''une grande université ?', 'Mon diplôme est-il en français ou en anglais ?', 'Mon diplôme est-il prestigieux ?', 'Mon diplôme me qualifie-t-il pour ce que je veux faire là-bas ?', 3, 'La leçon affirme clairement que la vraie question n''est pas si le diplôme est prestigieux, mais s''il qualifie pour le travail ou la formation souhaités.'),
  ('2-1-diplomes-ce-qui-compte-ce-qui-ne', 'module-2', 3, 'La catégorie de diplômes qui demande une reconnaissance (Anerkennung) concerne particulièrement quel domaine ?', 'Les métiers dits réglementés, notamment la santé', 'L''agriculture et le commerce', 'L''enseignement et l''éducation', 'L''informatique et les sciences', 0, 'La leçon indique que la catégorie deux concerne les métiers réglementés, avec la santé en premier lieu, qui doivent passer par une procédure officielle d''Anerkennung.'),
  ('2-1-diplomes-ce-qui-compte-ce-qui-ne', 'module-2', 4, 'Dans la catégorie trois de diplômes, qu''est-ce qui peut compter autant voire plus que le papier ?', 'La nationalité du candidat', 'L''expérience professionnelle réelle', 'La maîtrise de la langue allemande', 'Le nombre de formations suivies', 1, 'La leçon explique que pour l''Ausbildung et certains métiers en tension, l''expérience professionnelle réelle peut compter autant, voire plus, que le diplôme.'),
  ('2-1-diplomes-ce-qui-compte-ce-qui-ne', 'module-2', 5, 'Quel outil officiel allemand l''Allemagne propose-t-elle pour vérifier l''équivalence de son diplôme étranger ?', 'La chambre de commerce allemande (IHK)', 'Le registre fédéral d''emploi (BfA)', 'La base de données officielle anabin', 'Le portail national d''immigration (BAMF)', 2, 'La leçon mentionne anabin comme la base de données officielle qui recense les diplômes étrangers et leur équivalence, et que c''est l''outil de référence.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('2-2-la-reconnaissance-des-diplomes', 'module-2', 1, 'Qu''est-ce que l''Anerkennung en Allemagne ?', 'La reconnaissance officielle d''un diplôme ou d''une qualification par les autorités allemandes', 'Un permis de travail temporaire valable un an', 'Un examen d''intégration administré avant l''arrivée en Allemagne', 'Un cours d''allemand obligatoire pour les immigrants', 0, 'La leçon définit clairement l''Anerkennung comme ''la reconnaissance officielle de ton diplôme ou de ta qualification par les autorités allemandes''.'),
  ('2-2-la-reconnaissance-des-diplomes', 'module-2', 2, 'Quelle est la différence principale entre les métiers réglementés et les métiers non réglementés concernant la reconnaissance ?', 'Les métiers réglementés sont moins bien payés que les métiers non réglementés', 'Pour les métiers réglementés, la reconnaissance est obligatoire ; pour les autres, elle n''est pas toujours obligatoire', 'Les métiers non réglementés n''existent qu''en Allemagne', 'La reconnaissance est plus rapide pour les métiers non réglementés', 1, 'La leçon stipule que pour les métiers réglementés (santé, enseignement, droit), la reconnaissance est OBLIGATOIRE, tandis que pour les métiers non réglementés, elle n''est pas toujours obligatoire mais reste un avantage.'),
  ('2-2-la-reconnaissance-des-diplomes', 'module-2', 3, 'Que signifie une reconnaissance partielle lors de la demande d''Anerkennung ?', 'Le candidat doit attendre un an avant de pouvoir exercer son métier', 'Le diplôme n''est pas reconnu du tout et doit être complètement refait', 'Le diplôme est jugé presque équivalent, mais il manque certaines compétences et une mesure de compensation est proposée', 'La demande est acceptée mais uniquement pour une région spécifique d''Allemagne', 2, 'Selon la leçon, une reconnaissance partielle signifie que ''c''est presque équivalent, mais il manque telle ou telle compétence'' et ''on te propose une mesure de compensation — un stage, un examen, une formation d''adaptation''.'),
  ('2-2-la-reconnaissance-des-diplomes', 'module-2', 4, 'Quel conseil la leçon donne-t-elle pour optimiser le processus de reconnaissance ?', 'Déposer la demande seulement après avoir trouvé un emploi en Allemagne', 'Engager un avocat en Algérie pour gérer toute la procédure à distance', 'Attendre d''avoir obtenu une maîtrise parfaite de l''allemand avant de commencer la reconnaissance', 'Lancer la procédure de reconnaissance tôt, en parallèle de l''apprentissage de la langue, et même depuis l''Algérie', 3, 'La leçon souligne : ''si ta route demande une reconnaissance, lance-la TÔT. En parallèle de ton apprentissage de la langue'' et précise ''tu peux déposer ta demande de reconnaissance depuis l''Algérie''.'),
  ('2-2-la-reconnaissance-des-diplomes', 'module-2', 5, 'Qu''est-ce que l''Anerkennungspartnerschaft (partenariat de reconnaissance) introduit en mars 2024 ?', 'Un mécanisme permettant d''entrer et de travailler en Allemagne sous supervision tout en complétant la procédure de reconnaissance sur place', 'Une réduction des frais de demande de reconnaissance pour les ressortissants algériens', 'Un programme d''échange universitaire entre la France et l''Allemagne', 'Une possibilité de voyager en Allemagne sans visa pendant la procédure de reconnaissance', 0, 'La leçon explique que le partenariat de reconnaissance permet de ''ENTRER en Allemagne et commencer à travailler — sous supervision — pendant que tu termines ta procédure de reconnaissance sur place''.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('2-3-niveau-d-allemand-exige-par-voie', 'module-2', 1, 'Quel est le niveau d''allemand généralement requis pour débuter une formation Ausbildung en Allemagne ?', 'Aucun niveau spécifique n''est exigé pour commencer', 'A2, avec possibilité d''apprendre en travaillant', 'B1 au minimum, avec un B2 fortement recommandé', 'A1, car le niveau peut progresser rapidement durant la formation', 2, 'La leçon indique clairement que pour l''Ausbildung, on parle généralement de B1 au minimum pour commencer, avec un B2 fortement recommandé pour décrocher le contrat et réussir la formation.'),
  ('2-3-niveau-d-allemand-exige-par-voie', 'module-2', 2, 'Quelle est la principale différence concernant l''exigence d''allemand entre la Blue Card et les autres voies de travail qualifié ?', 'La Blue Card exige un C1 alors que le travail qualifié exige un B1', 'Aucune différence, les deux exigences sont identiques', 'La Blue Card exige un B2 alors que le travail qualifié exige un B1', 'La Blue Card n''exige aucun niveau d''allemand au moment de la demande, contrairement aux autres voies', 3, 'Selon la leçon, pour la Blue Card, aucun niveau d''allemand n''est exigé au moment de la demande — c''est le diplôme et le salaire qui comptent.'),
  ('2-3-niveau-d-allemand-exige-par-voie', 'module-2', 3, 'Pour la voie Chancenkarte, quel niveau minimum d''allemand est demandé si vous passez par le système à points ?', 'A1 en allemand OU un bon niveau d''anglais en B2', 'C1 pour montrer une maîtrise complète', 'Aucun niveau d''allemand, seulement l''anglais est accepté', 'B2 obligatoire en allemand', 0, 'La leçon précise que pour la Chancenkarte par système à points, on demande un A1 en allemand OU un bon niveau d''anglais en B2.'),
  ('2-3-niveau-d-allemand-exige-par-voie', 'module-2', 4, 'Quel niveau d''allemand est typiquement exigé pour la voie familiale (visa conjoint) ?', 'C1, pour une intégration réussie', 'Autour de A2, parfois A1 — l''une des routes les plus accessibles côté langue', 'B2, pour comprendre les administrations locales', 'B1, pour pouvoir converser au quotidien', 1, 'La leçon indique que pour la voie familiale, le niveau de départ est souvent bas — autour de A2, parfois A1, ce qui en fait l''une des routes les plus accessibles côté langue.'),
  ('2-3-niveau-d-allemand-exige-par-voie', 'module-2', 5, 'Pourquoi est-il important de viser le niveau d''allemand exact requis par votre route, plutôt que le plus haut possible ?', 'Parce que seul le niveau requis par votre route est reconnu officiellement', 'Parce que les niveaux plus élevés sont inutiles et coûtent plus cher à préparer', 'Parce que viser trop haut fait perdre des mois précieux pour rien, tandis que viser trop bas entraîne un refus', 'Parce que les autorités allemandes refusent les candidats trop qualifiés linguistiquement', 2, 'La leçon met en avant deux erreurs à éviter : viser trop haut fait perdre des mois précieux sans en avoir besoin, et viser trop bas entraîne un refus et une perte de frais.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('2-4-l-argent-a-prouver-combien-et-pourquoi', 'module-2', 1, 'Selon la leçon, quel est l''objectif principal de la preuve financière exigée par l''Allemagne ?', 'S''assurer que le candidat ne dépendra pas de l''aide publique pendant son installation', 'Vérifier que le candidat a déjà un travail en Allemagne avant d''arriver', 'Garantir que le candidat pourra louer un appartement sans dépôt de garantie', 'Assurer que le candidat est très riche et capable de dépenser beaucoup', 0, 'La leçon énonce clairement que l''Allemagne veut être sûre que le candidat peut subvenir à ses besoins sans dépendre de l''aide publique, le temps qu''il s''installe et gagne sa vie.'),
  ('2-4-l-argent-a-prouver-combien-et-pourquoi', 'module-2', 2, 'Dans le cas du Sperrkonto (compte bloqué), quelle est l''utilité de l''argent déposé ?', 'C''est un paiement unique pour obtenir le visa d''installation', 'C''est l''argent personnel du candidat qu''il peut récupérer mensuellement une fois sur place', 'C''est un prêt sans intérêt accordé par le gouvernement allemand', 'C''est de l''argent perdu au profit de l''État allemand', 1, 'La leçon précise que le Sperrkonto n''est pas de l''argent perdu, mais l''argent du candidat qu''il récupère mois après mois une fois en Allemagne, en retirant un montant fixe chaque mois.'),
  ('2-4-l-argent-a-prouver-combien-et-pourquoi', 'module-2', 3, 'Pour quelle route l''Ausbildung (apprentissage) doit-elle prouver sa capacité financière ?', 'En prouvant l''obtention d''une bourse du gouvernement allemand', 'À travers un compte bloqué élevé, obligatoire pour tous les apprentis', 'À travers son salaire d''apprenti, qui peut réduire ou annuler le besoin d''un compte bloqué', 'À travers un garant vivant en Allemagne qui prouve ses revenus', 2, 'La leçon indique que pour l''Ausbildung, c''est le salaire d''apprenti qui prouve la capacité à vivre, donc souvent pas de compte bloqué ou un montant réduit.'),
  ('2-4-l-argent-a-prouver-combien-et-pourquoi', 'module-2', 4, 'Dans le cas de la ''prise en charge'', qui doit apporter la preuve financière ?', 'L''employeur allemand du candidat', 'Une banque ou institution financière internationale', 'Le candidat qui demande l''immigration', 'Une personne déjà en Allemagne (conjoint ou proche) qui a les revenus et le logement pour accueillir', 3, 'La leçon explique que dans la prise en charge, c''est le garant déjà en Allemagne (conjoint ou proche) qui prouve qu''il a les revenus et le logement pour accueillir le candidat.'),
  ('2-4-l-argent-a-prouver-combien-et-pourquoi', 'module-2', 5, 'Selon la leçon, pourquoi est-il important d''anticiper la préparation de la preuve financière ?', 'Parce que l''ouverture du compte bloqué et la réunion des justificatifs prennent du temps', 'Parce que l''Allemagne refuse les demandes reçues avant trois mois', 'Parce que les taux de change changent chaque semaine', 'Parce que le montant du Sperrkonto triple si on l''ouvre à la dernière minute', 0, 'La leçon souligne que la preuve financière est une question de préparation, pas de richesse, car le compte bloqué prend du temps à ouvrir et alimenter, et les justificatifs du garant prennent aussi du temps à rassembler.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('3-1-a1-b2-de-quoi-tu-as-vraiment-besoin', 'module-3', 1, 'Selon le CECR, qu''est-ce que le niveau A1 permet de faire ?', 'Comprendre des discussions complexes et argumenter en allemand', 'Travailler et suivre une formation professionnelle', 'Survivre : se présenter, dire d''où tu viens, commander à manger, comprendre des phrases très simples', 'Tenir une conversation autonome et se débrouiller dans la plupart des situations', 2, 'La leçon définit A1 comme le niveau de « survivre » avec les capacités citées dans l''option B.'),
  ('3-1-a1-b2-de-quoi-tu-as-vraiment-besoin', 'module-3', 2, 'À partir de quel niveau l''Ausbildung est-elle souvent accessible ?', 'Uniquement au niveau B2', 'À partir du niveau C1', 'À partir du niveau A2', 'À partir du niveau B1', 3, 'La leçon indique que « l''Ausbildung [est] souvent à partir de B1 » et que B2 est recommandé pour vraiment réussir une Ausbildung.'),
  ('3-1-a1-b2-de-quoi-tu-as-vraiment-besoin', 'module-3', 3, 'Quel est le message central de la leçon concernant le niveau d''allemand à viser ?', 'Vise exactement le niveau de ta route, ni plus haut ni plus bas, pour ne pas gaspiller du temps', 'A1 et A2 suffisent pour toutes les démarches en Allemagne', 'Aucun niveau n''est vraiment nécessaire si tu es motivé', 'Vise toujours le niveau le plus haut possible, même si ce n''est pas nécessaire', 0, 'La leçon répète explicitement : « vise EXACTEMENT le niveau de ta route. Ni en dessous, ni au-dessus » et avertit que viser plus haut coûte des mois inutiles.'),
  ('3-1-a1-b2-de-quoi-tu-as-vraiment-besoin', 'module-3', 4, 'Quel est le niveau demandé pour la naturalisation en Allemagne selon la leçon ?', 'Le niveau A2', 'Le niveau B1', 'Le niveau B2', 'Le niveau A1', 1, 'La leçon mentionne que B1 est « le niveau demandé plus tard pour la naturalisation ».'),
  ('3-1-a1-b2-de-quoi-tu-as-vraiment-besoin', 'module-3', 5, 'Selon la leçon, combien de temps supplémentaire un C1 « pour être tranquille » pourrait-il te coûter ?', 'Environ deux à trois mois', 'Entre un et trois semaines', 'Entre six mois et un an', 'Plus de deux ans', 2, 'La leçon avertit qu''un C1 « te coûtera six mois à un an de plus — du temps que tu aurais pu passer à monter ton dossier ».')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('3-2-plan-d-apprentissage-rapide-et-pas-cher', 'module-3', 1, 'Selon la leçon, quel est le secret pour progresser vite dans l''apprentissage de l''allemand ?', 'Étudier 30 minutes à 1 heure régulièrement chaque jour', 'Suivre un cours avec un enseignant présent physiquement', 'Apprendre uniquement le vocabulaire technique dès le début', 'Faire 5 heures d''étude intensive chaque vendredi', 0, 'La leçon affirme que la régularité (30 minutes à 1 heure quotidienne) progresse bien plus vite que les gros blocs espacés, car le cerveau apprend par répétition rapprochée.'),
  ('3-2-plan-d-apprentissage-rapide-et-pas-cher', 'module-3', 2, 'Pourquoi la leçon recommande-t-elle de parler dès le premier jour d''apprentissage ?', 'Pour éviter que le cerveau n''oublie les mots après une semaine', 'Parce que sinon on accumule de la grammaire sans pratique orale et on devient paralysé lors d''examens ou d''entretiens', 'Parce qu''il est plus facile de parler avant d''apprendre à lire', 'Parce que c''est obligatoire pour obtenir un certificat de langue', 1, 'La leçon explique que la plupart des gens accumulent de la grammaire sans jamais parler, et le jour de l''examen oral ou de l''entretien, ils sont paralysés.'),
  ('3-2-plan-d-apprentissage-rapide-et-pas-cher', 'module-3', 3, 'Que signifie « apprendre en fonction de ton objectif » selon la leçon ?', 'Apprendre l''allemand de manière générale pendant au moins deux ans', 'Apprendre d''abord la grammaire avant le vocabulaire spécialisé', 'Se charger en vocabulaire spécifique à son domaine (médical, mécanique, etc.) plutôt que d''apprendre l''allemand généraliste', 'Utiliser uniquement des ressources gratuites pour maîtriser l''objectif', 2, 'La leçon indique que si on vise la santé, il faut charger en vocabulaire médical dès que possible, et si on vise l''Ausbildung en mécanique, il faut du vocabulaire technique — apprendre l''allemand de TA route, pas l''allemand « en général ».'),
  ('3-2-plan-d-apprentissage-rapide-et-pas-cher', 'module-3', 4, 'Quel problème la leçon identifie-t-elle spécifiquement au sujet du Goethe-Institut d''Alger ?', 'Il propose des cours mais trop chers pour la plupart des Algériens', 'Il refuse les candidats algériens', 'Il n''existe pas en Algérie', 'Il ne propose que les examens, pas les cours', 3, 'La leçon mentionne explicitement que « pour l''instant, le Goethe-Institut d''Alger ne donne pas de cours, seulement les examens ».'),
  ('3-2-plan-d-apprentissage-rapide-et-pas-cher', 'module-3', 5, 'Pourquoi la leçon affirme-t-elle que le gratuit seul ne suffit presque jamais ?', 'Parce qu''il n''y a personne pour corriger tes erreurs ni structurer ta progression', 'Parce que le gratuit ne couvre pas la grammaire avancée', 'Parce que les certificats reconnus ne sont pas gratuits', 'Parce que les applications gratuites contiennent des erreurs', 0, 'La leçon explique que « le gratuit seul ne suffit presque jamais à atteindre un bon niveau, parce qu''il n''y a personne pour corriger tes erreurs ni structurer ta progression ».')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('3-3-goethe-telc-sd-quel-certificat-choisir', 'module-3', 1, 'Selon la leçon, quel est le critère légal DÉCISIF pour l''immigration en Allemagne en matière de certificat d''allemand ?', 'L''ancienneté du certificat, obtenu depuis moins de 6 mois', 'Le nom et la réputation mondiale de l''organisme certificateur', 'Le NIVEAU du Cadre européen (A1, B1, B2), pas la marque de l''organisme', 'Le certificat Goethe, car c''est le seul reconnu légalement', 2, 'La leçon stipule clairement que ce qui compte légalement, c''est le NIVEAU du Cadre européen, pas le nom de l''organisme — un B1 telc vaut un B1 Goethe aux yeux de l''administration allemande.'),
  ('3-3-goethe-telc-sd-quel-certificat-choisir', 'module-3', 2, 'Quel organisme certificateur proposera une version spécialisée pour les professionnels de la santé ?', 'Aucun organisme n''offre de spécialisation médicale', 'Le Goethe-Zertifikat avec son module médical obligatoire', 'L''ÖSD, qui est l''organisme autrichien', 'Le telc, notamment avec le telc B2 Pflege pour la reconnaissance des infirmiers', 3, 'La leçon précise que le telc propose des versions spécialisées, notamment le telc B2 Pflege souvent exigé pour la reconnaissance des infirmiers en Allemagne.'),
  ('3-3-goethe-telc-sd-quel-certificat-choisir', 'module-3', 3, 'Le certificat B1 a été développé conjointement par quels deux organismes ?', 'Le Goethe et l''ÖSD, et ils sont quasiment identiques', 'Le telc et l''ÖSD', 'Le Goethe seul, qui l''a exporte ensuite', 'Le Goethe et le telc', 0, 'La leçon indique que le certificat B1 a été développé conjointement par le Goethe et l''ÖSD, et qu''ils sont quasiment identiques.'),
  ('3-3-goethe-telc-sd-quel-certificat-choisir', 'module-3', 4, 'Quelle est la validité maximale exigée pour un certificat de langue au moment du dépôt du visa ?', 'Moins de 6 mois', 'Moins d''un an', 'Moins de 18 mois', 'Aucune limite de validité n''est imposée', 1, 'La leçon mentionne qu''un point crucial est que le certificat doit généralement dater de moins d''un an au moment du dépôt du visa.'),
  ('3-3-goethe-telc-sd-quel-certificat-choisir', 'module-3', 5, 'Selon la leçon, dans quels pays le Goethe-Zertifikat est-il présent mondialement ?', 'Dans 150 pays à travers le monde', 'Dans 50 pays environ', 'Dans plus de 90 pays', 'Uniquement en Allemagne et en Autriche', 2, 'La leçon décrit le Goethe-Zertifikat comme le plus connu mondialement, le plus prestigieux, présent dans plus de 90 pays.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('3-4-ou-passer-l-examen-depuis-l-algerie', 'module-3', 1, 'Où peux-tu passer ton examen d''allemand officiel en Algérie ?', 'Au Goethe-Institut d''Alger', 'Dans les centres de formation privés autorisés', 'En ligne sur la plateforme du ministère de l''Éducation', 'Dans n''importe quel lycée algérien agréé par le gouvernement', 0, 'La leçon indique clairement que le Goethe-Institut d''Alger administre les examens d''allemand officiels, du niveau débutant aux niveaux avancés.'),
  ('3-4-ou-passer-l-examen-depuis-l-algerie', 'module-3', 2, 'Quel est le point important que beaucoup d''Algériens découvrent trop tard concernant le Goethe-Institut d''Alger ?', 'L''examen coûte très cher et n''est pas accessible à tous', 'Il administre les examens mais ne donne PAS de cours de langue actuellement', 'Il refuse les candidates femmes sans autorisation familiale', 'Les certificats qu''il délivre ne sont pas reconnus en Allemagne', 1, 'La leçon souligne que le Goethe-Institut administre les EXAMENS mais ne donne PAS de cours — il faut donc apprendre la langue ailleurs, en ligne ou dans une structure sérieuse.'),
  ('3-4-ou-passer-l-examen-depuis-l-algerie', 'module-3', 3, 'Quel document officiel dois-tu prévoir lors de ton inscription à l''examen ?', 'Un diplôme de fin d''études secondaires', 'Une lettre de motivation en allemand', 'Un passeport biométrique', 'Une attestation bancaire prouvant ta solvabilité', 2, 'La leçon précise explicitement que tu dois avoir ton passeport biométrique, car il est exigé pour l''inscription à l''examen.'),
  ('3-4-ou-passer-l-examen-depuis-l-algerie', 'module-3', 4, 'Combien d''épreuves composent l''examen d''allemand et quel est le critère pour valider ton certificat ?', '5 épreuves ; tu dois obtenir au minimum 60% de réussite', '3 épreuves ; tu dois obtenir une moyenne de 50%', '4 épreuves ; tu dois réussir au moins 2 modules sur 4', '4 épreuves ; tu dois réussir TOUS les modules', 3, 'La leçon énumère les quatre épreuves (compréhension écrite, compréhension orale, expression écrite, expression orale) et indique clairement que pour valider ton certificat, tu dois réussir TOUS les modules.'),
  ('3-4-ou-passer-l-examen-depuis-l-algerie', 'module-3', 5, 'Qu''est-ce qu''un certificat officiel du Goethe-Institut et pourquoi est-ce important pour ton dossier d''immigration ?', 'C''est un document officiel reconnu internationalement que tu dois récupérer après réussite, pas une simple attestation de cours', 'C''est une lettre de recommandation personnelle de ton professeur', 'C''est un badge numérique émis sur internet sans valeur administrative', 'C''est une simple attestation de présence à un cours de langue', 0, 'La leçon souligne que c''est un document officiel — pas une simple attestation de cours — qui te servira pour ton dossier d''immigration, et que les résultats sortent en quelques semaines.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('4-1-la-checklist-complete-des-documents', 'module-4', 1, 'Comment sont organisés les documents à rassembler pour votre dossier d''immigration en Allemagne selon cette leçon ?', 'Selon le classement alphabétique des noms de documents', 'En trois catégories : personnels, financiers et professionnels', 'En deux catégories : le socle commun et le spécifique à ta route', 'Par ordre chronologique de demande auprès des autorités', 2, 'La leçon explique clairement cette organisation en deux catégories : le socle commun (documents dont presque tout le monde a besoin) et le spécifique (documents propres à ta route choisie).'),
  ('4-1-la-checklist-complete-des-documents', 'module-4', 2, 'Parmi les éléments suivants, lequel ne fait PAS partie du socle commun de documents ?', 'Les diplômes, relevés de notes et photos biométriques', 'Le passeport biométrique valide', 'Les actes d''état civil et le casier judiciaire', 'Un contrat de travail pour le travail qualifié', 3, 'Le contrat de travail est un document spécifique à la route du travail qualifié, pas partie du socle commun. Le socle commun est demandé pour presque tout le monde, peu importe la route choisie.'),
  ('4-1-la-checklist-complete-des-documents', 'module-4', 3, 'Quel est le principal conseil donné concernant le moment de créer son dossier de documents ?', 'Créer le dossier maintenant, en parallèle des autres démarches, car certains documents prennent des semaines', 'Attendre d''avoir terminé la leçon de langue avant de rassembler les documents', 'Préparer le dossier une fois que la reconnaissance des diplômes est complète', 'Commencer une semaine avant le rendez-vous à l''ambassade', 0, 'La leçon souligne la règle d''or : créer son dossier MAINTENANT car certains documents prennent des semaines, et le dossier se construit en parallèle de tout le reste (langue, reconnaissance).'),
  ('4-1-la-checklist-complete-des-documents', 'module-4', 4, 'Quel document est présenté comme la priorité absolue à vérifier en premier ?', 'Les actes d''état civil traduits', 'Le passeport biométrique et sa date d''expiration', 'Les diplômes et relevés de notes', 'Le casier judiciaire', 1, 'À la fin de la leçon, il est indiqué que le passeport conditionne tous les autres documents, et que c''est le premier à vérifier — sa validité est cruciale car son renouvellement peut prendre du temps.'),
  ('4-1-la-checklist-complete-des-documents', 'module-4', 5, 'Quelle est la plus grande cause de refus de dossier selon cette leçon ?', 'Un âge trop avancé', 'Un profil professionnel inadapté', 'Un dossier incomplet ou mal préparé', 'Une langue allemande insuffisante', 2, 'La leçon introduit directement le sujet en affirmant : la cause numéro un de refus n''est pas un mauvais profil, c''est un dossier incomplet ou mal préparé.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('4-2-traduction-assermentee-ou-et-comment', 'module-4', 1, 'Pourquoi ne peut-on pas simplement traduire soi-même ses documents pour l''Allemagne ?', 'Parce que seules les traductions par un traducteur assermenté ont une valeur légale reconnue', 'Parce que les autorités allemandes n''acceptent que les traductions très coûteuses', 'Parce que les documents en français ne sont jamais acceptés en Allemagne', 'Parce que l''Allemagne interdit les traductions personnelles par manque de contrôle', 0, 'Selon la leçon, une traduction par soi-même ou par un traducteur non assermenté n''a aucune valeur légale, même si elle est parfaite. Seule la traduction par un traducteur assermenté officiellement habilité est reconnue.'),
  ('4-2-traduction-assermentee-ou-et-comment', 'module-4', 2, 'Quelles sont les deux options principales pour obtenir une traduction assermentée ?', 'Un traducteur diplômé en Algérie ou un logiciel de traduction automatique', 'Un traducteur assermenté en Algérie ou un traducteur assermenté en Allemagne (vereidigter Übersetzer)', 'Un ami germanoophone ou un traducteur spécialisé dans l''immigration', 'Un traducteur allemand ou un traducteur français', 1, 'La leçon énonce clairement ces deux options : un traducteur assermenté en Algérie, ou un « vereidigter Übersetzer » reconnu en Allemagne.'),
  ('4-2-traduction-assermentee-ou-et-comment', 'module-4', 3, 'Quel est le conseil crucial AVANT de payer des traductions ?', 'Attendre de recevoir une réponse de l''autorité avant de commencer le dossier', 'Chercher le traducteur le moins cher possible pour économiser', 'Vérifier auprès de son autorité (ambassade, organisme, université) ce qu''elle accepte exactement', 'Faire traduire immédiatement tous les documents en arabe et en français', 2, 'La leçon souligne que c''est crucial de vérifier ce que l''autorité précise accepte AVANT de payer, car différentes autorités peuvent avoir des exigences légèrement différentes.'),
  ('4-2-traduction-assermentee-ou-et-comment', 'module-4', 4, 'Parmi les documents suivants, lequel n''a généralement PAS besoin d''être traduit ?', 'Le casier judiciaire', 'Les actes d''état civil', 'Les diplômes et relevés de notes', 'Le passeport', 3, 'La leçon indique explicitement : « Pas besoin de traduire ton passeport en général. » Les autres documents (actes d''état civil, diplômes, casier judiciaire) doivent être traduits.'),
  ('4-2-traduction-assermentee-ou-et-comment', 'module-4', 5, 'Pourquoi est-il important de vérifier l''exigence de l''autorité avant de payer les traductions ?', 'Pour éviter de payer des traductions qui ne seraient pas acceptées et de devoir tout refaire', 'Parce que certains traducteurs algériens refusent de traduire pour l''Allemagne', 'Parce que les traductions en Allemagne coûtent toujours plus cher', 'Pour obtenir une réduction de prix auprès du traducteur', 0, 'La leçon avertit : « Rien de pire que de payer un jeu complet de traductions, puis d''apprendre qu''elles ne sont pas acceptées et de devoir tout refaire. Une question posée à temps t''économise du temps et de l''argent. »')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('4-3-l-apostille-etape-par-etape-la', 'module-4', 1, 'Depuis quelle date l''Algérie a-t-elle changé son système de légalisation des documents en rejoignant la Convention Apostille ?', 'Le 1er septembre 2025', 'Le 1er janvier 2025', 'Le 9 juillet 2026', 'Le 15 mars 2026', 2, 'La leçon indique explicitement que depuis le 9 juillet 2026, l''Algérie a changé de système en rejoignant la Convention de La Haye.'),
  ('4-3-l-apostille-etape-par-etape-la', 'module-4', 2, 'Quel était le principal problème du système ancien de légalisation des documents algériens ?', 'Il était impossible de légaliser un document sans passer par l''Allemagne directement', 'Les documents ne pouvaient être authentifiés que par une plateforme numérique', 'Les documents ne pouvaient être traduits que dans une seule langue', 'Il fallait passer par plusieurs étapes : commune, ministère, Affaires étrangères, consulat, ce qui prenait plusieurs semaines', 3, 'La leçon précise que l''ancien système nécessitait une légalisation en plusieurs étapes (commune, ministère, ministère des Affaires étrangères, consulat) avec plusieurs semaines d''attente.'),
  ('4-3-l-apostille-etape-par-etape-la', 'module-4', 3, 'Qu''est-ce que l''apostille apporte concrètement pour les documents algériens en Allemagne ?', 'Un cachet ou une certification unique reconnu directement en Allemagne sans autre légalisation', 'Un passage obligatoire au consulat allemand pour la validation finale', 'Une augmentation du délai de traitement administrative', 'Une traduction certifiée du document en allemand', 0, 'Selon la leçon, l''apostille est un cachet ou une certification unique apposé sur le document qui le rend reconnu directement en Allemagne, sans aucune autre légalisation nécessaire.'),
  ('4-3-l-apostille-etape-par-etape-la', 'module-4', 4, 'En quelles langues l''apostille algérienne est-elle prévue pour faciliter sa reconnaissance à l''étranger ?', 'Français et anglais', 'Arabe et anglais', 'Arabe, français et anglais', 'Arabe et français', 1, 'La leçon indique que l''apostille algérienne est prévue en version bilingue, arabe et anglais, ce qui facilite sa reconnaissance à l''étranger.'),
  ('4-3-l-apostille-etape-par-etape-la', 'module-4', 5, 'Quel conseil important la leçon donne-t-elle concernant l''ordre entre la traduction et l''apostille ?', 'La traduction doit toujours se faire avant l''apostille, obligatoirement', 'L''apostille doit obligatoirement précéder la traduction', 'Il faut vérifier l''ordre attendu auprès de l''autorité allemande car il peut varier selon les cas', 'L''ordre n''a aucune importance et on peut les faire dans n''importe quel sens', 2, 'La leçon souligne qu''il faut vérifier l''ordre attendu par l''autorité allemande avant de lancer la procédure, car c''est un détail qui peut obliger à tout recommencer s''il est mal fait.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('4-4-les-erreurs-de-dossier-qui-causent-un-refus', 'module-4', 1, 'Selon la leçon, quel est le risque principal d''un dossier incomplet lors d''une demande d''immigration en Allemagne ?', 'L''administration allemande refuse généralement le dossier sans chercher à réclamer la pièce manquante', 'Le candidat peut compléter le dossier dans les trois mois sans conséquence', 'Seuls les documents traduits peuvent causer un refus s''ils sont incomplets', 'L''administration allemande enverra un courrier pour demander le document manquant après deux semaines', 0, 'La leçon précise qu''un seul document manquant peut suspendre ou faire refuser le dossier, car l''administration allemande ne court pas après le candidat pour réclamer la pièce manquante.'),
  ('4-4-les-erreurs-de-dossier-qui-causent-un-refus', 'module-4', 2, 'Quelle précaution est recommandée avant de payer une traduction auprès d''un traducteur ?', 'Toujours faire traduire par un traducteur algérien assermenté, accepté partout en Allemagne', 'Vérifier auprès de l''autorité allemande compétente si elle accepte le type de traduction que tu envisages, avant de payer', 'Faire traduire uniquement en France pour garantir une acceptation', 'Faire plusieurs traductions par des traducteurs différents pour augmenter les chances d''acceptation', 1, 'La leçon insiste sur le fait de vérifier AVANT de payer ce que l''autorité accepte, car une traduction refusée fait perdre des semaines et les exigences varient selon l''autorité.'),
  ('4-4-les-erreurs-de-dossier-qui-causent-un-refus', 'module-4', 3, 'Pourquoi les documents périmés constituent-ils une erreur grave dans un dossier d''immigration ?', 'Seuls les certificats de langue ont une limite de validité, les autres pièces ne périment jamais', 'Ils n''ont aucune importance, l''administration regarde surtout la date de dépôt du dossier', 'Beaucoup de pièces ont une durée de validité limité (casier judiciaire trop ancien, certificat de langue de plus d''un an, etc.), et une pièce qui expire entre la réunion et le dépôt cause un problème', 'Les documents périmés font automatiquement refuser le dossier entier sans aucune exception', 2, 'La leçon explique que de nombreuses pièces ont une durée de validité (casier judiciaire, acte, certificat de langue) et qu''une pièce peut expirer entre la réunion du dossier et son dépôt.'),
  ('4-4-les-erreurs-de-dossier-qui-causent-un-refus', 'module-4', 4, 'Qu''est-ce que la leçon entend par l''erreur du « mauvais ordre » ?', 'Envoyer le dossier par courrier classique au lieu de courrier recommandé', 'Remplir les formulaires en commençant par le bas au lieu de commencer par le haut', 'Classer les documents en ordre alphabétique au lieu de l''ordre chronologique', 'Faire les démarches dans le désordre, par exemple demander un visa avant d''avoir la pièce qui doit exister en premier, ou payer les traductions avant de savoir si l''apostille doit venir avant ou après', 3, 'La leçon souligne que chaque route a une séquence logique à respecter, et que le mauvais ordre (par exemple payer les traductions avant de connaître l''ordre de l''apostille) crée des problèmes.'),
  ('4-4-les-erreurs-de-dossier-qui-causent-un-refus', 'module-4', 5, 'Comment les incohérences dans un dossier affectent-elles sa probabilité d''acceptation ?', 'Même de petites incohérences (nom orthographié différemment entre documents, dates qui ne collent pas) sèment le doute et peuvent bloquer le dossier', 'Les incohérences ne causent jamais un refus, seulement un délai d''un mois pour vérification', 'Les petites incohérences sont ignorées par l''administration allemande si le profil du candidat est excellent', 'Les incohérences n''ont d''impact que si elles concernent le salaire ou l''expérience professionnelle', 0, 'La leçon explique que les petites incohérences (un nom orthographié différemment entre le passeport et le diplôme, une date qui ne colle pas) sèment le doute et bloquent les dossiers.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('5-1-le-lebenslauf-comment-un', 'module-5', 1, 'Quel est le format standard du CV allemand qui assure une évaluation rapide par le recruteur ?', 'Un format libre sans structure précise pour montrer sa créativité', 'Un format narratif avec de longs paragraphes détaillant chaque expérience', 'Le Lebenslauf tabulaire (tabellarischer Lebenslauf) en deux colonnes avec dates à gauche', 'Un CV au format américain avec photo et signature', 2, 'La leçon précise que le standard est le ''tabellarischer Lebenslauf'', structuré en deux colonnes avec dates à gauche et expérience/formation à droite, permettant au recruteur d''évaluer le parcours en moins d''une minute.'),
  ('5-1-le-lebenslauf-comment-un', 'module-5', 2, 'Dans quel ordre doit-on présenter son expérience professionnelle et sa formation sur un Lebenslauf allemand ?', 'Selon le secteur d''activité choisi par le candidat', 'Du plus ancien au plus récent pour montrer une évolution chronologique', 'Par importance du poste, du plus important au moins important', 'De la plus récente à la plus ancienne (antéchronologique)', 3, 'La leçon stipule clairement que l''ordre est antéchronologique : l''expérience la plus récente en haut, car le recruteur voit d''abord ce que tu fais maintenant, ce qui décrit le mieux ta capacité actuelle.'),
  ('5-1-le-lebenslauf-comment-un', 'module-5', 3, 'Que doit indiquer un candidat pour spécifier son niveau de langue sur un Lebenslauf allemand ?', 'Les niveaux européens (A1, A2, B1, B2, C1, C2)', 'Uniquement les langues officielles du pays d''origine', 'Une description générale comme ''bon niveau d''anglais'' ou ''allemand courant''', 'Le nombre d''années d''apprentissage de la langue', 0, 'La leçon souligne que les langues doivent être indiquées avec le niveau européen (A1 à C2), par exemple ''Allemand B1'', car cela parle immédiatement aux recruteurs allemands.'),
  ('5-1-le-lebenslauf-comment-un', 'module-5', 4, 'Quelle est la situation légale concernant la photo sur un Lebenslauf allemand ?', 'La photo est obligatoire par la loi allemande depuis 2020', 'Elle n''est pas légalement obligatoire en raison des lois anti-discrimination, mais elle reste largement attendue dans la pratique', 'La photo est formellement interdite pour tous les candidats', 'Elle est obligatoire uniquement pour certains secteurs comme le secteur public', 1, 'La leçon précise que légalement la photo n''est pas obligatoire en raison des lois anti-discrimination, mais que dans la pratique, surtout dans les secteurs traditionnels et les PME, une photo professionnelle reste largement attendue.'),
  ('5-1-le-lebenslauf-comment-un', 'module-5', 5, 'Quelles données personnelles doit-on inclure sur un Lebenslauf allemand ?', 'Toutes les informations personnelles, y compris l''état civil et la situation familiale', 'Seulement le nom et l''adresse email, comme en France', 'Nom, coordonnées, date et lieu de naissance, et nationalité — plus complet que le standard français', 'Uniquement le nom, l''email et le numéro de téléphone', 2, 'La leçon indique que les données personnelles en Allemagne incluent traditionnellement plus de détails : nom, coordonnées, date et lieu de naissance, nationalité — ce qui est différent du standard français et est attendu par les recruteurs allemands.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('5-2-la-lettre-de-motivation-anschreiben', 'module-5', 1, 'Combien de pages doit faire l''Anschreiben (lettre de motivation) selon la leçon ?', 'Exactement une page', 'Deux à trois pages au maximum', 'Autant de pages que nécessaire pour bien se présenter', 'Entre une et deux pages, selon la longueur du CV', 0, 'La leçon énonce clairement en règle stricte que l''Anschreiben fait exactement UNE page, car les Allemands valorisent la concision et la précision.'),
  ('5-2-la-lettre-de-motivation-anschreiben', 'module-5', 2, 'Quelle est la différence principale entre le Lebenslauf (CV) et l''Anschreiben (lettre) selon la leçon ?', 'Le CV est un argumentaire tandis que la lettre est une liste factuelle', 'Le CV est une liste tandis que la lettre est un argumentaire expliquant pourquoi vous pour ce poste', 'Le CV doit être formel alors que la lettre peut être plus personnelle', 'Il n''y a pas de différence significative, c''est juste un formalisme', 1, 'La leçon explique que le Lebenslauf est une LISTE de faits, tandis que l''Anschreiben est un ARGUMENTAIRE qui répond à la question : pourquoi TOI, pour CE poste, dans CETTE entreprise.'),
  ('5-2-la-lettre-de-motivation-anschreiben', 'module-5', 3, 'Pourquoi ne faut-il pas répéter le contenu du CV dans la lettre de motivation ?', 'Parce qu''il est interdit par la loi du travail allemand', 'Parce que cela augmente inutilement le nombre de pages', 'Parce que la lettre doit relier ton parcours au besoin précis de l''employeur, pas reproduire tes faits', 'Parce que les recruteurs allemands n''aiment pas lire deux fois les mêmes informations', 2, 'La leçon précise que la lettre doit servir d''ARGUMENTAIRE : utilise-la pour relier ton parcours au besoin précis de l''employeur, pas pour répéter le CV.'),
  ('5-2-la-lettre-de-motivation-anschreiben', 'module-5', 4, 'Quel ton doit-on adopter dans l''Anschreiben allemand ?', 'Enthusiaste et motivé, en montrant votre passion depuis l''enfance', 'Amical et personnel, avec des anecdotes émouvantes', 'Créatif et original, pour se démarquer des autres candidats', 'Formel, factuel, professionnel et direct, sans familiarité ni exagération', 3, 'La leçon stipule que le ton allemand est formel et factuel, sans familiarité ni exagération, et précise qu''on ne doit pas écrire qu''on ''rêve depuis l''enfance'' mais plutôt démontrer une adéquation professionnelle.'),
  ('5-2-la-lettre-de-motivation-anschreiben', 'module-5', 5, 'Comment doit-on adapter la lettre de motivation au poste visé ?', 'Adapter chaque lettre au poste spécifique en reprenant les mots-clés de l''offre d''emploi', 'Adapter seulement le nom de l''entreprise et l''intitulé du poste', 'Faire une lettre unique très complète qui fonctionne pour tous les postes', 'Utiliser le même modèle générique pour tous les postes, plus pratique et rapide', 0, 'La leçon met l''accent sur l''importance d''adapter CHAQUE lettre au poste : reprendre les mots-clés de l''annonce et montrer qu''on a compris ce que l''employeur cherche, car une lettre générique se repère immédiatement.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('5-3-photo-format-details-qui-comptent', 'module-5', 1, 'Selon la leçon, quel est le format de fichier recommandé pour envoyer ta candidature ?', 'Excel, pour mieux organiser les informations personnelles', 'Word (.docx), car c''est le format le plus courant', 'PDF, pour que la mise en page reste intacte quel que soit l''ordinateur du recruteur', 'Google Docs, pour faciliter la collaboration avec les recruteurs', 2, 'La leçon stipule clairement : ''envoie en PDF, jamais en Word : le PDF garde ta mise en page intacte quel que soit l''ordinateur du recruteur''.'),
  ('5-3-photo-format-details-qui-comptent', 'module-5', 2, 'Que dois-tu absolument éviter pour ta photo de candidature ?', 'Les photos en tenue professionnelle', 'Les photos prises par un photographe professionnel', 'Les photos avec fond bleu clair', 'Les selfies ou photos de vacances recadrées', 3, 'La leçon indique : ''Pas un selfie, pas une photo de vacances recadrée'' et affirme qu''une mauvaise photo fait plus de mal que pas de photo du tout.'),
  ('5-3-photo-format-details-qui-comptent', 'module-5', 3, 'Quelle(s) police(s) de caractères est(sont) recommandée(s) pour le CV en Allemagne ?', 'Arial, Calibri ou Times New Roman en taille 11 ou 12', 'Impact en taille 14 pour plus de visibilité', 'Georgia en taille 9 pour un rendu épuré', 'Comic Sans ou Brush Script pour un rendu plus original', 0, 'La leçon précise : ''une police lisible et classique — Arial, Calibri, Times New Roman — taille 11 ou 12''.'),
  ('5-3-photo-format-details-qui-comptent', 'module-5', 4, 'En Allemagne, que sont les ''Arbeitszeugnisse'' et comment dois-tu les gérer si tu viens d''Algérie ?', 'Ce sont des permis de travail ; tu dois en demander un au gouvernement allemand', 'Ce sont des certificats de travail délivrés par l''employeur, et si tu n''en as pas, fournis des lettres de référence', 'Ce sont des documents d''assurance ; tu peux les ignorer lors de ta candidature', 'Ce sont des diplômes universitaires ; tu dois les faire reconnaître avant de postuler', 1, 'La leçon explique : ''les fameux Arbeitszeugnisse. En Allemagne, l''employeur est légalement tenu d''en délivrer un... Si tu n''en as pas — ce qui est souvent le cas quand on vient d''Algérie — fournis des lettres de référence de tes anciens employeurs à la place''.'),
  ('5-3-photo-format-details-qui-comptent', 'module-5', 5, 'Combien de pages peut contenir une Bewerbung (candidature complète) allemande et c''est normal ?', 'Maximum 2 à 3 pages, sinon elle sera considérée comme trop longue', 'Entre 5 et 8 pages pour être compétitif', 'Entre 10 et 20 pages, et c''est normal en Allemagne avec tous les documents joints', 'Plus de 30 pages pour montrer que tu as de l''expérience', 2, 'La leçon affirme : ''L''ensemble, bien rangé, dans un ordre logique, peut faire dix à vingt pages — et c''est normal en Allemagne''.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('5-4-modeles-prets-a-remplir', 'module-5', 1, 'Quel est le premier des trois documents que tu reçois en bonus dans cette leçon ?', 'Un modèle de Lebenslauf tabulaire aux normes allemandes', 'Des modèles d''emails pour contacter les employeurs', 'Un guide des entreprises allemandes à cibler', 'Un modèle d''Anschreiben avec structure complète', 0, 'La leçon énumère d''abord le modèle de Lebenslauf tabulaire avec deux colonnes, les bonnes sections et l''emplacement de la photo comme premier document reçu.'),
  ('5-4-modeles-prets-a-remplir', 'module-5', 2, 'Que dois-tu absolument faire avec le texte entre crochets dans les modèles selon la première règle ?', 'Le laisser tel quel pour montrer que tu maîtrises le format', 'Le remplacer entièrement par tes propres informations', 'L''adapter légèrement pour gagner du temps', 'Le garder comme exemple pour que l''employeur comprenne la structure', 1, 'La règle un stipule clairement : « remplace TOUT le texte entre crochets » et la leçon précise que ne pas le faire est « l''erreur classique qui fait tâche ».'),
  ('5-4-modeles-prets-a-remplir', 'module-5', 3, 'Quelle est la deuxième règle pour bien utiliser les modèles fournis ?', 'Traduire le modèle dans ta langue maternelle avant d''envoyer', 'Envoyer le même modèle à tous les employeurs sans modification', 'Adapter le modèle à chaque offre en reprenant les mots-clés de l''annonce', 'Utiliser uniquement le modèle d''Anschreiben et ignorer le Lebenslauf', 2, 'La règle deux indique explicitement : « adapte à chaque offre » et précise que « le modèle est une base, pas un copier-coller universel » et qu''il faut « reprendre les mots-clés de chaque annonce ».'),
  ('5-4-modeles-prets-a-remplir', 'module-5', 4, 'Quel est le rôle de la troisième règle d''utilisation des modèles ?', 'Confirmer que le modèle a été envoyé à au moins 10 employeurs', 'Vérifier que tous les crochets ont bien été supprimés', 'S''assurer que le Lebenslauf comporte une photo obligatoire', 'Faire relire la candidature pour éviter les fautes d''allemand', 3, 'La règle trois explique : « fais relire » et justifie que « une faute d''allemand dans une candidature, ça se voit et ça pénalise » et recommande de faire vérifier par quelqu''un de niveau supérieur.'),
  ('5-4-modeles-prets-a-remplir', 'module-5', 5, 'Après la fin du Module 5, quel est le prochain sujet abordé dans le Module 6 ?', 'Où trouver les offres, comment contacter directement les employeurs et repérer les arnaques', 'Comment négocier ton salaire avec l''employeur', 'Les procédures de visa et d''installation en Allemagne', 'Comment perfectionner ton allemand écrit', 0, 'La leçon conclut en annonçant : « Dans le Module 6, on passe à la chasse : où trouver les offres, comment contacter directement les employeurs, et comment repérer les arnaques ».')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('6-1-ou-chercher-sites-portails-agences-reelles', 'module-6', 1, 'Quel est le nom de la plus grande base d''offres d''emploi en Allemagne, gérée par l''État ?', 'XING', 'StepStone', 'Jobbörse de l''Agence fédérale pour l''emploi (Bundesagentur für Arbeit)', 'Make it in Germany', 2, 'La leçon identifie explicitement la Jobbörse de la Bundesagentur für Arbeit comme « la plus grande base d''offres d''Allemagne, des centaines de milliers d''offres, gérée par l''État ».'),
  ('6-1-ou-chercher-sites-portails-agences-reelles', 'module-6', 2, 'Quel portail officiel du gouvernement est particulièrement recommandé pour les candidats internationaux qui cherchent un emploi en Allemagne ?', 'Ausbildung-portal', 'EURES', 'XING', 'Make it in Germany', 3, 'Selon la leçon, Make it in Germany est « le portail officiel du gouvernement pour les internationaux » et « est plus accessible en anglais, donne les infos visa, et reprend des offres de la Jobbörse ».'),
  ('6-1-ou-chercher-sites-portails-agences-reelles', 'module-6', 3, 'Si tu es en Algérie et tu prépares une Chancenkarte, quel portail est particulièrement utile pour explorer les offres en avance ?', 'EURES', 'LinkedIn uniquement', 'Les sites des entreprises directement', 'StepStone', 0, 'La leçon précise que EURES est « particulièrement utile si tu es encore en Algérie et que tu prépares une Chancenkarte — tu explores les offres avant même d''arriver ».'),
  ('6-1-ou-chercher-sites-portails-agences-reelles', 'module-6', 4, 'Pour une Ausbildung (formation professionnelle), où dois-tu chercher les offres selon la leçon ?', 'Uniquement sur Indeed', 'Sur les portails spécialisés Ausbildung dédiés à la formation', 'Seulement sur les sites des entreprises', 'Principalement via les agences de placement', 1, 'La leçon explique que pour l''Ausbildung, « il y a des portails dédiés — des sites spécialisés dans les places de formation, souvent avec des milliers d''offres et des outils pour candidats internationaux ».'),
  ('6-1-ou-chercher-sites-portails-agences-reelles', 'module-6', 5, 'Quel conseil la leçon donne-t-elle avant de t''engager avec une agence de placement privée ?', 'Éviter complètement toutes les agences privées', 'Accepter toujours leurs conditions car ce sont des professionnels', 'Te renseigner sur les frais AVANT de t''engager et vérifier leur réputation', 'Leur faire confiance sans vérification puisqu''elles sont officielles', 2, 'La leçon énonce une « règle absolue » : « renseigne-toi sur les frais AVANT de t''engager, et vérifie leur réputation » pour les agences de placement privées.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('6-2-contacter-un-employeur-une-ecole-directement', 'module-6', 1, 'Qu''est-ce que l''Initiativbewerbung, selon la leçon ?', 'Une candidature spontanée envoyée à une entreprise même sans poste ouvert affiché', 'Un formulaire obligatoire exigé par l''État allemand pour tous les candidats étrangers', 'Une lettre de motivation dont la structure est strictement imposée par la loi', 'Une candidature soumise uniquement en réponse à une annonce d''emploi publiée', 0, 'La leçon définit l''Initiativbewerbung comme la candidature spontanée : tu envoies ta candidature à une entreprise même sans poste ouvert affiché.'),
  ('6-2-contacter-un-employeur-une-ecole-directement', 'module-6', 2, 'Selon la leçon, pourquoi la candidature spontanée est-elle efficace ?', 'Parce que beaucoup de candidats l''utilisent déjà et tu arrives avant les autres', 'Parce que beaucoup de besoins ne sont jamais publiés et tu peux arriver au bon moment', 'Parce que l''Allemagne manque totalement de candidats qualifiés', 'Parce qu''elle est obligatoire en Allemagne', 1, 'La leçon explique que beaucoup de besoins ne sont jamais publiés — tu peux arriver au bon moment avec une candidature spontanée.'),
  ('6-2-contacter-un-employeur-une-ecole-directement', 'module-6', 3, 'Quelle est la première étape de la méthode présentée dans la leçon ?', 'Envoyer un message court et précis avec ton CV', 'Trouver le responsable du recrutement ou le service RH', 'Constituer une liste d''entreprises ou d''établissements qui correspondent à ta route et à ton métier', 'Relancer l''entreprise après deux semaines si tu n''as pas de réponse', 2, 'La leçon énonce clairement que la première étape est de cibler et de faire une liste d''entreprises qui correspondent à ta route et à ton métier.'),
  ('6-2-contacter-un-employeur-une-ecole-directement', 'module-6', 4, 'Que conseille la leçon concernant le contact à privilégier ?', 'Contacter directement le directeur général de l''entreprise', 'Envoyer ta candidature à au moins 5 personnes différentes dans la même entreprise', 'Envoyer toujours à l''adresse générique info@ pour rejoindre tous les services', 'Chercher le responsable du recrutement, le service RH, ou la personne en charge de la formation plutôt qu''une adresse générique', 3, 'La leçon affirme qu''il faut chercher la bonne personne (responsable RH, recrutement ou formation) car un message à la bonne personne vaut dix messages dans le vide.'),
  ('6-2-contacter-un-employeur-une-ecole-directement', 'module-6', 5, 'Quel point concernant le suivi (Nachfassen) la leçon dit-elle que les Algériens oublient souvent ?', 'De relancer poliment une fois après une à deux semaines si pas de réponse', 'De vérifier les coordonnées de l''entreprise avant d''envoyer le CV', 'De traduire leur CV du français à l''allemand', 'D''envoyer une première candidature complète', 0, 'La leçon souligne que les Algériens oublient souvent le suivi : relancer poliment une fois après une à deux semaines est important et beaucoup de candidatures aboutissent grâce à cette relance.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('6-3-les-messages-qui-obtiennent-une-reponse', 'module-6', 1, 'Quel est le premier ingrédient d''un bon message de contact pour une demande d''emploi en Allemagne ?', 'Un lien vers ton profil LinkedIn', 'Une phrase de présentation personnelle du candidat', 'Un objet clair qui dit tout de suite ce que tu veux', 'Une lettre de motivation détaillée sur ta carrière', 2, 'La leçon indique clairement que le premier ingrédient est un objet clair : dis tout de suite ce que tu veux, comme le poste ou le type de formation recherché.'),
  ('6-3-les-messages-qui-obtiennent-une-reponse', 'module-6', 2, 'Pourquoi est-il important d''écrire le message en allemand selon la leçon ?', 'C''est moins important que l''orthographe du message', 'L''anglais fonctionne aussi bien en Allemagne', 'C''est obligatoire et tout message en anglais sera rejeté', 'Cela montre l''effort et le sérieux, même si l''allemand est imparfait', 3, 'La leçon précise que l''allemand, même imparfait, montre l''effort et le sérieux. L''anglais peut dépanner pour certains secteurs, mais l''allemand est toujours mieux vu.'),
  ('6-3-les-messages-qui-obtiennent-une-reponse', 'module-6', 3, 'Quel élément le candidat doit-il absolument inclure à la fin de son message de contact ?', 'Un appel à l''action simple et son CV en pièce jointe', 'Une liste détaillée de ses certifications et diplômes', 'Un lien vers un site internet personnel ou un portfolio', 'Un numéro de téléphone personnel et une adresse email de secours', 0, 'Le quatrième ingrédient mentionné dans la leçon est un appel à l''action simple et le CV en pièce jointe, avec l''exemple : ''Je serais ravi d''échanger. Vous trouverez mon CV ci-joint.'''),
  ('6-3-les-messages-qui-obtiennent-une-reponse', 'module-6', 4, 'La leçon recommande quel type de contenu pour la deuxième partie du message ?', 'Une biography détaillée de tes études et expériences professionnelles', 'Une phrase courte disant qui tu es et ce que tu cherches', 'Un résumé des raisons pour lesquelles tu veux travailler en Allemagne', 'Une explication de ta situation personnelle et familiale', 1, 'La leçon indique que le deuxième ingrédient est une phrase courte qui dit qui tu es et ce que tu cherches, avec l''exemple : ''Je suis infirmier diplômé, je cherche un poste en Pflege et je prépare ma reconnaissance.'''),
  ('6-3-les-messages-qui-obtiennent-une-reponse', 'module-6', 5, 'Selon la leçon, quel détail critique doit être absolument correct dans un message de contact ?', 'La couleur et le format du CV envoyé', 'Le nombre de pages du message', 'Le nom de l''entreprise et de la personne', 'La date d''envoi du message', 2, 'La leçon souligne que le nom de l''entreprise et de la personne, surtout, doivent être justes. C''est un détail crucial qui montre le respect et l''attention.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('6-4-reconnaitre-les-arnaques-et-faux-recruteurs', 'module-6', 1, 'Selon la leçon, pourquoi un vrai employeur en Allemagne ne te demande jamais de payer pour un emploi ?', 'Parce que c''est lui qui te paie, pas l''inverse.', 'Parce qu''il vérifie d''abord si tu as de l''argent.', 'Parce que l''État allemand l''interdit formellement.', 'Parce qu''il te fournit d''abord une formation gratuite.', 0, 'Un vrai employeur te paie un salaire — il n''a aucune raison de te demander de l''argent en échange d''un emploi. Si quelqu''un te le demande, c''est presque toujours une arnaque.'),
  ('6-4-reconnaitre-les-arnaques-et-faux-recruteurs', 'module-6', 2, 'Quel est l''un des signaux d''alerte liés aux promesses dans une offre d''emploi ou de visa ?', 'On te promet une formation en allemand gratuite.', 'On te promet un visa garanti en deux semaines ou un salaire énorme sans qualification.', 'On te promet un contrat de travail signé.', 'On te promet un logement fourni par l''entreprise.', 1, 'Les promesses irréalistes comme ''visa garanti en deux semaines'', ''salaire énorme sans qualification'' ou ''pas besoin d''allemand'' contredisent ce qu''on apprend dans la formation — ce sont des drapeaux rouges d''arnaque.'),
  ('6-4-reconnaitre-les-arnaques-et-faux-recruteurs', 'module-6', 3, 'Comment peux-tu vérifier qu''une entreprise ou agence est légitime ?', 'En lui envoyant une demande d''emploi pour voir si elle répond.', 'En demandant à des amis s''ils en ont entendu parler.', 'En cherchant son nom, en vérifiant qu''elle a un site sérieux, une adresse et un numéro d''entreprise vérifiables.', 'En lui téléphonant directement pour demander des références.', 2, 'Une vraie entreprise ou agence a une existence vérifiable — site sérieux, adresse vérifiable, numéro d''entreprise. L''absence de ces traces est un signal d''alerte clair.'),
  ('6-4-reconnaitre-les-arnaques-et-faux-recruteurs', 'module-6', 4, 'Quel type de pression est un outil classique utilisé par les arnaqueurs ?', 'Te poser des questions sur ta formation et tes compétences.', 'Te demander de passer un test de langue en allemand.', 'Te demander de références professionnelles.', 'Te créer de l''urgence artificielle (par exemple : ''décide aujourd''hui ou tu perds ta place'').', 3, 'L''urgence artificielle (''paie maintenant, l''offre expire ce soir'') empêche le candidat de réfléchir et de vérifier — c''est une tactique classique des arnaqueurs. Un processus légitime te laisse le temps de vérifier.'),
  ('6-4-reconnaitre-les-arnaques-et-faux-recruteurs', 'module-6', 5, 'Quels sont les canaux recommandés par la leçon pour chercher des offres d''emploi sans risque d''arnaque ?', 'Les portails officiels du gouvernement, la Jobbörse, Make it in Germany, où le risque d''arnaque est quasi nul.', 'Les petites agences locales sans site internet mais avec bonne réputation locale.', 'Les offres envoyées directement par email par des recruteurs inconnus.', 'Les groupes Facebook privés et les messageries personnelles d''agents de recrutement.', 0, 'La leçon recommande de privilégier toujours les canaux officiels — portails du gouvernement, Jobbörse, Make it in Germany — où le risque d''arnaque est quasi nul.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('7-1-quel-visa-pour-ta-situation', 'module-7', 1, 'Quelle est la principale différence entre un visa Schengen touristique et un visa national allemand de long séjour ?', 'Il n''y a aucune différence réelle, ils sont juste nommés différemment.', 'Le visa Schengen permet de rester plus longtemps mais ne permet pas de travailler.', 'Le visa national permet de s''installer et de travailler en Allemagne pour plus de 90 jours, contrairement au visa touristique.', 'Le visa national est réservé aux étudiants, tandis que le visa Schengen est pour tous les visiteurs.', 2, 'La leçon établit clairement que le visa national de long séjour est destiné aux séjours de plus de 90 jours et permet de s''installer et de travailler, contrairement au visa Schengen touristique.'),
  ('7-1-quel-visa-pour-ta-situation', 'module-7', 2, 'Pour quelqu''un ayant un diplôme hautement qualifié en informatique et cherchant un emploi d''ingénieur en Allemagne, quel type de visa national devrait-il demander ?', 'Un visa étudiant pour finaliser une admission.', 'Un visa pour formation professionnelle (Ausbildung).', 'Un visa de regroupement familial.', 'Un visa de travailleur qualifié, et potentiellement la Carte Bleue européenne s''il remplit les conditions de salaire.', 3, 'Selon la leçon, le travail qualifié correspond à un visa de travailleur qualifié, et si les conditions de salaire et de diplôme sont remplies, la Carte Bleue européenne peut être envisagée.'),
  ('7-1-quel-visa-pour-ta-situation', 'module-7', 3, 'Où est-ce qu''une personne obtient son visa national allemand initial ?', 'En Algérie, avant de partir pour l''Allemagne.', 'À la frontière allemande, au poste douanier.', 'En ligne, sur le site officiel du gouvernement allemand, avant le départ.', 'Une fois arrivée en Allemagne, auprès de l''administration locale des étrangers.', 0, 'La leçon précise que le visa d''entrée s''obtient en Algérie ; c''est ensuite en Allemagne qu''il est transformé en titre de séjour.'),
  ('7-1-quel-visa-pour-ta-situation', 'module-7', 4, 'Quel est le lien entre la ''route'' d''immigration et le choix du visa ?', 'La route n''a aucun impact sur le visa — tous les visas sont identiques.', 'Chaque route d''immigration (travail, études, santé, famille, etc.) correspond à un visa national spécifique.', 'La route détermine uniquement la durée du visa, pas son type.', 'Le choix de la route se fait après l''obtention du visa, pas avant.', 1, 'La leçon établit que ''le visa national correspond à ta route'' et énumère les visas spécifiques pour chaque route : travail qualifié, Chancenkarte, Ausbildung, études, santé, regroupement familial.'),
  ('7-1-quel-visa-pour-ta-situation', 'module-7', 5, 'Quel est le processus correct après obtention du visa national allemand en Algérie ?', 'Le visa d''entrée est remplacé par une simple carte d''identité de résident.', 'Le visa permet automatiquement de rester et travailler en Allemagne sans démarches supplémentaires.', 'Le visa d''entrée doit être transformé en titre de séjour auprès de l''administration locale des étrangers une fois en Allemagne.', 'Il faut demander une nouvelle autorisation gouvernementale chaque mois pour continuer à rester.', 2, 'La leçon explique le principe en deux temps : le visa d''entrée obtenu en Algérie te fait entrer en Allemagne, et une fois sur place, tu dois le transformer en titre de séjour auprès de l''administration des étrangers.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('7-2-blue-card-chancenkarte-fachkr-fte', 'module-7', 1, 'Quel est le principal avantage de la Blue Card en termes de langue ?', 'Aucun niveau d''allemand n''est exigé au moment de la demande', 'Un certificat A1 en allemand est obligatoire pour valider la demande', 'Il faut justifier d''une formation linguistique en cours', 'L''allemand doit être maîtrisé au niveau B1 minimum', 0, 'Selon la leçon, pour la Blue Card, aucun niveau d''allemand n''est exigé au moment de la demande — c''est le diplôme et le contrat qui comptent.'),
  ('7-2-blue-card-chancenkarte-fachkr-fte', 'module-7', 2, 'Laquelle de ces trois voies ne demande PAS d''offre d''emploi à l''avance ?', 'Le Fachkräftevisum', 'La Chancenkarte', 'Aucune — toutes les trois exigent une offre', 'La Blue Card', 1, 'La Chancenkarte est la seule qui ne demande pas d''offre d''emploi à l''avance ; c''est un système à points permettant de chercher un emploi sur place pendant un an.'),
  ('7-2-blue-card-chancenkarte-fachkr-fte', 'module-7', 3, 'Pour quel type de demandeur la Chancenkarte est-elle la solution idéale ?', 'Les demandeurs qui parlent déjà l''allemand couramment', 'Les titulaires d''un master en informatique avec un très bon salaire', 'Les personnes qui n''ont pas encore d''employeur identifié', 'Les infirmiers diplômés ayant une offre en début de carrière', 2, 'Selon la leçon, la Chancenkarte est le ''tremplin idéal si tu n''as pas encore d''employeur'', permettant de venir chercher un emploi sur place.'),
  ('7-2-blue-card-chancenkarte-fachkr-fte', 'module-7', 4, 'Qu''est-ce qui distingue le Fachkräftevisum de la Blue Card en termes d''accès au marché du travail ?', 'Le Fachkräftevisum demande un niveau d''allemand minimum, la Blue Card ne l''exige pas', 'Le Fachkräftevisum est réservé aux métiers paramédicaux', 'Le Fachkräftevisum n''accepte que les diplômes universitaires, la Blue Card accepte tous les diplômes', 'Le Fachkräftevisum s''adresse aux personnes ayant une offre qualifiée en dessous du seuil de salaire de la Blue Card', 3, 'La leçon explique que le Fachkräftevisum concerne ceux ''dont le salaire n''atteint pas forcément le seuil de la Blue Card'', pour des qualifications reconnues (universitaire OU professionnelle).'),
  ('7-2-blue-card-chancenkarte-fachkr-fte', 'module-7', 5, 'Après avoir obtenu une Chancenkarte et trouvé un emploi qualifié en Allemagne, que doit faire le demandeur ?', 'Convertir sa Chancenkarte en Blue Card ou en visa de travailleur qualifié', 'Faire valider son contrat auprès des autorités algériennes', 'Attendre 12 mois avant de signer un contrat officiel', 'Continuer à chercher un autre emploi pour avoir plus d''options', 0, 'Selon la leçon, ''une fois que tu as trouvé et signé un contrat qualifié, tu convertis ta Chancenkarte en Blue Card ou en visa de travailleur qualifié''.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('7-3-la-demande-en-ligne-et-le', 'module-7', 1, 'En quelle année l''Allemagne a-t-elle déployé son portail consulaire numérique pour les demandes de visa ?', 'En 2024', 'En 2025', 'En 2026', 'En 2027', 2, 'La leçon affirme clairement que depuis début 2026, l''Allemagne a déployé son portail consulaire numérique.'),
  ('7-3-la-demande-en-ligne-et-le', 'module-7', 2, 'Combien de visites en personne à la représentation allemande sont nécessaires pour compléter ta demande de visa selon le nouveau système ?', 'Deux visites (une pour vérifier les documents, une pour les biométriques)', 'Aucune, tout est en ligne', 'Au moins trois visites (demande, documents, biométriques)', 'Une seule visite pour les biométriques', 3, 'La leçon précise qu''il reste une seule étape en personne : le rendez-vous pour les données biométriques (vérification d''identité, empreintes et photo).'),
  ('7-3-la-demande-en-ligne-et-le', 'module-7', 3, 'Quel est l''objectif de délai annoncé par le nouveau système pour traiter les demandes de visa ?', 'Quatre à six semaines', 'Huit à dix semaines', 'Douze à seize semaines', 'Deux à quatre semaines', 0, 'La leçon indique que l''objectif du nouveau système est de descendre vers quatre à six semaines pour beaucoup de demandes, contre huit à douze semaines avant.'),
  ('7-3-la-demande-en-ligne-et-le', 'module-7', 4, 'À quelle étape du processus dois-tu payer les frais de visa ?', 'Avant de remplir la demande en ligne', 'Après le téléversement des documents, avant de prendre le rendez-vous biométrique', 'Uniquement au rendez-vous biométrique', 'Après avoir reçu une notification d''approbation', 1, 'Selon les 6 étapes énumérées dans la leçon, l''étape 4 consiste à payer les frais et prendre le rendez-vous biométrique après avoir téléversé les documents.'),
  ('7-3-la-demande-en-ligne-et-le', 'module-7', 5, 'Pourquoi la leçon recommande-t-elle de vérifier régulièrement le portail consulaire officiel ?', 'Pour réserver des rendez-vous plusieurs mois à l''avance', 'Pour connaître les nouveaux tarifs de visa qui changent chaque mois', 'Parce que le système est récent, évolue constamment, et que toutes les catégories ne sont pas identiques selon les pays', 'Pour télécharger les formulaires à imprimer', 2, 'La leçon explique que comme le système est récent et évolue, et que toutes les catégories et tous les pays ne sont pas encore identiques, il faut vérifier la procédure exacte sur le portail officiel au moment de la demande.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('7-4-remplir-les-formulaires-sans-erreur', 'module-7', 1, 'Selon la leçon, pourquoi est-il crucial que toutes les informations de ton formulaire correspondent exactement à tes documents ?', 'Parce que la moindre incohérence sème le doute et bloque le dossier.', 'Parce que c''est une règle administrative sans impact réel.', 'Parce que cela réduit le délai de traitement.', 'Parce que cela impressionne les agents consulaires.', 0, 'La leçon énonce clairement que toute incohérence, même mineure (exemple : orthographe du nom), « sème le doute et bloque le dossier ».'),
  ('7-4-remplir-les-formulaires-sans-erreur', 'module-7', 2, 'Qu''arrive-t-il si tu déposes une demande de visa dans la mauvaise catégorie ?', 'Tu peux la corriger facilement lors du rendez-vous.', 'La demande repart à zéro.', 'L''agent consulaire te guidera vers la bonne catégorie automatiquement.', 'C''est accepté tant que tu fournis tous les documents.', 1, 'La leçon précise que si tu remplis la demande pour le mauvais type de visa, « une demande dans la mauvaise catégorie repart à zéro ».'),
  ('7-4-remplir-les-formulaires-sans-erreur', 'module-7', 3, 'Si une question obligatoire sur le formulaire ne s''applique pas à ta situation, que dois-tu faire ?', 'La laisser complètement vide.', 'Écrire « N/A » ou un tiret et passer à la suite.', 'L''indiquer correctement plutôt que de la laisser vide.', 'Contacter le consulat pour demander l''autorisation de la sauter.', 2, 'La leçon enseigne que si une question ne s''applique pas, il faut « l''indiquer correctement plutôt que de laisser vide », car les réponses manquantes ralentissent le traitement.'),
  ('7-4-remplir-les-formulaires-sans-erreur', 'module-7', 4, 'Quel est l''impact d''un scan illisible ou d''un document manquant lors de la soumission de ton dossier ?', 'Cela n''a aucun impact sur le traitement.', 'L''agent consulaire te rappellera pour que tu le corriges rapidement.', 'Le dossier est automatiquement accepté mais marqué comme incomplet.', 'Le dossier est suspendu.', 3, 'La leçon indique clairement que « un scan illisible ou un document manquant, et ton dossier est suspendu ».'),
  ('7-4-remplir-les-formulaires-sans-erreur', 'module-7', 5, 'La leçon recommande de faire relire ta demande par quelqu''un d''autre avant de la soumettre. Pour quelle raison ?', 'Parce qu''un regard neuf repère les fautes que tu ne vois plus.', 'C''est obligatoire pour tous les demandeurs.', 'Pour que la personne signe avec toi comme témoin.', 'Pour impressionner le consulat avec une demande très soignée.', 0, 'La leçon explique que faire relire par quelqu''un d''autre aide parce que « un regard neuf repère les fautes que tu ne vois plus », et c''est particulièrement utile si tu bénéficies d''un accompagnement.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('8-1-ce-qu-on-te-demande-vraiment', 'module-8', 1, 'Selon la leçon, quel est l''objectif RÉEL de l''agent d''immigration lors d''un entretien ?', 'Confirmer que tu as un salaire minimum de référence en Allemagne', 'Vérifier que tu as choisi l''Allemagne pour les bonnes raisons économiques', 'Déterminer si tu es sincère, cohérent, et si tu vas vraiment faire ce que tu dis', 'Évaluer tes connaissances en culture générale allemande', 2, 'La leçon énonce clairement que la seule question derrière toutes les questions est : ''Cette personne est-elle sincère, cohérente, et va-t-elle vraiment faire ce qu''elle dit ?'''),
  ('8-1-ce-qu-on-te-demande-vraiment', 'module-8', 2, 'Combien de thèmes principaux les questions de l''agent tournent-elles autour, selon la leçon ?', 'Six thèmes : étudiant, apprenti, travailleur, famille, documents et langue', 'Trois thèmes : financement, motivation et expérience', 'Cinq thèmes : passé, présent, avenir, financement et santé', 'Quatre thèmes : pourquoi l''Allemagne, pourquoi cette voie, comment tu finances, quels sont tes projets', 3, 'La leçon énumère explicitement quatre thèmes autour desquels les questions tournent : ''Pourquoi l''Allemagne'', ''Pourquoi cette voie précise'', ''Comment tu finances ton séjour'' et ''Quels sont tes projets''.'),
  ('8-1-ce-qu-on-te-demande-vraiment', 'module-8', 3, 'Que signifie exactement ''court'' dans la règle d''or pour répondre aux questions ?', 'Utiliser le moins de mots possibles pour limiter les risques de contradiction', 'Donner des réponses sans détail pour ne pas paraître trop préparé', 'Ignorer les parties secondaires de la question posée', 'Répondre en moins de trente secondes par question', 0, 'La leçon justifie ''court'' ainsi : ''parce que plus tu parles, plus tu risques de te contredire'', ce qui montre que l''objectif est de minimiser les contradictions.'),
  ('8-1-ce-qu-on-te-demande-vraiment', 'module-8', 4, 'Quel élément de ta candidature l''agent vérifie particulièrement quand il demande ''Comment finances-tu ton séjour'' ?', 'Que tu as déjà commencé à travailler en Allemagne', 'Que tu peux subvenir à tes besoins (compte bloqué, salaire, prise en charge)', 'Que tu as emprunté l''argent auprès d''une banque allemande', 'Que tu comptes demander des allocations gouvernementales allemandes', 1, 'La leçon précise : ''On vérifie que tu peux subvenir à tes besoins — ton compte bloqué, ton salaire, ta prise en charge.'''),
  ('8-1-ce-qu-on-te-demande-vraiment', 'module-8', 5, 'Selon la leçon, qu''est-ce que l''agent repère instantanément chez un candidat et qui constitue un problème ?', 'Une préférence pour une ville autre que Berlin ou Munich', 'Un accent algérien trop marqué dans son français', 'Le discours appris par cœur et les mensonges', 'Un manque de diplômes certifiés par l''État allemand', 2, 'La leçon énonce : ''Honnête, parce que les agents repèrent le discours appris par cœur et les mensonges.''')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('8-2-preparer-tes-reponses-aux-questions-frequentes', 'module-8', 1, 'Selon la leçon, comment dois-tu préparer tes réponses aux questions fréquentes lors d''un entretien ?', 'En préparant les idées principales et en sachant comment les exprimer avec tes propres mots.', 'En improvisant entièrement le jour de l''entretien pour paraître plus naturel.', 'En écrivant un texte complet que tu lisas directement à l''agent.', 'En apprenant par cœur chaque réponse mot pour mot, pour montrer ta préparation.', 0, 'La leçon affirme clairement qu''il ne faut pas apprendre par cœur, car une réponse récitée sonne faux et inquiète l''agent : tu dois préparer les idées et savoir les dire avec tes propres mots.'),
  ('8-2-preparer-tes-reponses-aux-questions-frequentes', 'module-8', 2, 'Quand tu réponds à « Pourquoi l''Allemagne ? », qu''est-ce que la leçon te recommande de faire ?', 'Donner une raison générale et vague pour plaire à tous les agents.', 'Relier une raison concrète et personnelle à ce que l''Allemagne offre dans ton domaine spécifique.', 'Énumérer tous les avantages économiques de l''Allemagne par rapport aux autres pays.', 'Avouer que tu ne sais pas vraiment pourquoi tu as choisi l''Allemagne.', 1, 'La leçon conseille d''éviter les clichés vagues et d''être spécifique à ta situation : relie tes opportunités concrètes dans ton domaine et la qualité de formation à TA situation personnelle.'),
  ('8-2-preparer-tes-reponses-aux-questions-frequentes', 'module-8', 3, 'Quel élément la leçon qualifie-t-elle d''« astuce la plus puissante » pour rassurer l''agent lors de l''entretien ?', 'Avoir une tenue professionnelle impeccable et un bon sourire.', 'Apprendre l''allemand couramment avant l''entretien.', 'Connaître son propre dossier sur le bout des doigts (employeur, école, ville, montants financiers).', 'Amener des documents officieux supplémentaires non demandés.', 2, 'La leçon énonce explicitement que l''astuce la plus puissante est de connaître son propre dossier parfaitement : un candidat qui hésite sur les détails de son projet inquiète immédiatement, tandis que celui qui les connaît rassure.'),
  ('8-2-preparer-tes-reponses-aux-questions-frequentes', 'module-8', 4, 'À la question « Comment finances-tu ton séjour ? », avec quels détails précis dois-tu répondre ?', 'Une estimation approximative, car les agents ne vérifieront pas les détails.', 'Les tarifs des logements et des restaurants en Allemagne.', 'Uniquement le montant total sans détailler la source de financement.', 'Ton compte bloqué, ton contrat et salaire, ou ta prise en charge, en connaissant tes chiffres.', 3, 'La leçon indique de répondre avec précision et calme en donnant les montants spécifiques de ton compte bloqué, contrat, salaire ou prise en charge, car les agents vérifient ce point de près.'),
  ('8-2-preparer-tes-reponses-aux-questions-frequentes', 'module-8', 5, 'Pourquoi la leçon recommande-t-elle de s''entraîner à voix haute pour préparer tes réponses ?', 'Pour être fluide et à l''aise, plutôt que pour mémoriser, idéalement avec quelqu''un qui te pose les questions.', 'Parce que les agents n''aiment pas les candidats qui lisent leurs réponses.', 'Pour développer ta voix et parler plus fort le jour de l''entretien.', 'Pour devenir capable de réciter parfaitement chaque réponse sans erreur.', 0, 'La leçon précise que l''entraînement vocal sert à devenir fluide et à l''aise, pas à réciter, et recommande de le faire si possible avec quelqu''un qui pose les questions, notamment via une simulation d''entretien.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('8-3-prouver-que-tu-peux-te-financer', 'module-8', 1, 'Selon la leçon, quelle est la raison principale pour laquelle les dossiers d''immigration solides sont refusés à cause de la preuve financière ?', 'Parce que les banques algériennes refusent les virements internationaux', 'Parce que les gens n''ont pas assez d''argent en Algérie', 'Parce que la preuve est présentée de manière insuffisante ou peu claire', 'Parce que l''Allemagne refuse systématiquement les candidats algériens', 2, 'La leçon précise explicitement : ''Pas parce que les gens n''ont pas l''argent, mais parce qu''ils présentent mal cette preuve.'''),
  ('8-3-prouver-que-tu-peux-te-financer', 'module-8', 2, 'Quelles sont les trois formes de preuve financière acceptées en Allemagne selon la leçon ?', 'Titre de propriété, salaire et emprunt bancaire', 'Donation familiale, épargne personnelle et crédit immobilier', 'Salaire, contrat et lettre d''un ami riche', 'Compte bloqué, salaire et contrat, ou prise en charge par un garant', 3, 'La leçon énumère clairement : ''compte bloqué, salaire et contrat, ou prise en charge par un garant.'''),
  ('8-3-prouver-que-tu-peux-te-financer', 'module-8', 3, 'Quel piège courant consiste à faire un gros dépôt d''argent juste avant le rendez-vous ?', 'Cela éveille les soupçons et fait penser que le financement n''est pas stable', 'Cela accélère systématiquement le traitement du dossier', 'Cela n''a aucun impact sur la décision de l''agent', 'C''est autorisé et recommandé pour impressionner l''agent', 0, 'La leçon avertit : ''Un gros dépôt juste avant le rendez-vous éveille les soupçons. Un financement doit paraître stable et logique, pas surgi de nulle part la veille.'''),
  ('8-3-prouver-que-tu-peux-te-financer', 'module-8', 4, 'Selon la leçon, comment qualifier la preuve financière pour maximiser ses chances d''approbation ?', 'Riche, impressionnante, maximale et négociable', 'Clair, stable, cohérent, avec marge', 'Complexe, détaillée, professionnelle et élaborée', 'Simple, basique, rapide et minimale', 1, 'La leçon formule la parade en quatre mots : ''La parade tient en quatre mots : clair, stable, cohérent, avec marge.'''),
  ('8-3-prouver-que-tu-peux-te-financer', 'module-8', 5, 'Quel est l''objectif principal de l''agent lorsqu''il examine ta preuve financière ?', 'Contrôler que tes parents sont millionnaires', 'Vérifier que tu as plus d''argent que les citoyens allemands', 'S''assurer que tu pourras vivre en Allemagne sans difficulté le temps de t''installer', 'Confirmer que tu as un compte bancaire depuis au moins dix ans', 2, 'La leçon énonce clairement : ''L''agent veut une seule certitude : que tu pourras vivre en Allemagne sans tomber dans la difficulté, le temps de t''installer.''')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('8-4-gerer-le-stress-et-eviter-les-erreurs', 'module-8', 1, 'Selon la leçon, quel est le moment recommandé pour préparer tous tes documents (originaux et copies) ?', 'La veille du rendez-vous, dans l''ordre demandé', 'Une semaine avant, pour avoir le temps de vérifier', 'Sur place, juste avant l''entretien', 'Le matin du rendez-vous pour être sûr qu''ils sont à jour', 0, 'La leçon stipule clairement : « prépare tous tes documents la veille, originaux et copies, dans l''ordre demandé. Ne laisse rien pour le matin même. »'),
  ('8-4-gerer-le-stress-et-eviter-les-erreurs', 'module-8', 2, 'Que dois-tu faire si tu ne connais pas la réponse à une question pendant l''entretien ?', 'Refuser poliment de répondre et passer à la question suivante', 'Dire calmement que tu ne sais pas', 'Demander à l''officier de te donner un indices pour t''aider', 'Inventer une réponse plausible pour montrer ta confiance', 1, 'La leçon affirme : « Si tu ne sais pas, dis-le calmement plutôt que d''inventer. Inventer se voit. »'),
  ('8-4-gerer-le-stress-et-eviter-les-erreurs', 'module-8', 3, 'Selon la leçon, quelle est la principale raison d''arriver à l''heure ou en avance au rendez-vous ?', 'Pour pouvoir relire ton dossier une fois de plus avant l''entretien', 'Pour montrer que tu es une personne très ponctuelle par nature', 'Pour éviter que l''entretien commence mal et pour avoir le temps de te calmer', 'Pour impressionner l''officier d''immigration avec ton sérieux', 2, 'La leçon explique : « Arriver en retard ou essoufflé démarre l''entretien dans le mauvais sens. »'),
  ('8-4-gerer-le-stress-et-eviter-les-erreurs', 'module-8', 4, 'En 2026, selon la leçon, quel risque court-on si le dossier contient une incohérence ou un document douteux ?', 'On te demande seulement une explication verbale', 'Rien de grave, car les erreurs mineures sont acceptées', 'On te donne une chance de corriger immédiatement sur place', 'On peut entraîner un refus technique, sans qu''on te demande forcément de corriger', 3, 'La leçon prévient : « Une incohérence ou un document douteux peut entraîner un refus technique, sans qu''on te demande forcément de corriger. »'),
  ('8-4-gerer-le-stress-et-eviter-les-erreurs', 'module-8', 5, 'Quelle formule résume la stratégie générale proposée par la leçon pour réussir ton entretien d''immigration ?', 'Préparé + calme + cohérent = tu réussis', 'Documenté + parlant + sympathique = tu réussis', 'Honnête + rapide + nerveux = tu réussis', 'Stressé + rapide + créatif = tu réussis', 0, 'La leçon énonce clairement cette formule clé à la fin : « Préparé + calme + cohérent = tu réussis »')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('8-4-quoi-faire-en-cas-de-refus', 'module-8', 1, 'Qu''est-ce que la « remonstration » mentionnée dans cette leçon, et quel est son statut aujourd''hui ?', 'Un dépôt administratif de nouvelles preuves financières auprès de l''Allemagne qui coûte 50 euros', 'Un processus d''appel auprès de l''Auswärtiges Amt qui dure 6 mois', 'Un recours gratuit à l''ambassade allemande qui a été supprimé depuis le 1er juillet 2025', 'Une procédure judiciaire payante devant le tribunal administratif de Berlin qui est toujours disponible', 2, 'Selon la leçon, la remonstration était un recours gratuit à l''ambassade pour contester un refus de visa, mais ce droit a été SUPPRIMÉ par l''Allemagne mondialement depuis le 1er juillet 2025.'),
  ('8-4-quoi-faire-en-cas-de-refus', 'module-8', 2, 'Après avoir reçu un refus de visa, combien d''options légales exactes te reste-t-il selon cette leçon ?', 'Quatre : redéposer, recours judiciaire, demander une révision administrative, ou contacter le ministère des Affaires étrangères', 'Une seule : redéposer immédiatement avec un dossier renforcé', 'Trois : redéposer, recours judiciaire, ou demander une remonstration gratuite', 'Deux : redéposer une nouvelle demande ou un recours judiciaire au tribunal administratif de Berlin', 3, 'La leçon énonce clairement qu''après un refus, tu as exactement DEUX options : redéposer une nouvelle demande (la plus recommandée) ou le recours en justice devant le tribunal administratif de Berlin.'),
  ('8-4-quoi-faire-en-cas-de-refus', 'module-8', 3, 'Pourquoi la leçon recommande-t-elle de redéposer un nouveau dossier plutôt que de choisir le recours judiciaire ?', 'Parce que redéposer est plus rapide, plus efficace et moins coûteux qu''une procédure judiciaire payante et longue', 'Parce que le recours judiciaire ne s''applique qu''aux refus de permis de travail, pas de visa', 'Parce que redéposer garantit automatiquement l''acceptation au deuxième essai', 'Parce que le recours judiciaire n''existe pas en Allemagne', 0, 'La leçon explique que le recours judiciaire est ''une procédure judiciaire, payante, qui prend du temps et coûte cher'', tandis que redéposer un dossier corrigé est ''plus rapide et plus efficace'' pour la plupart des gens.'),
  ('8-4-quoi-faire-en-cas-de-refus', 'module-8', 4, 'Quel est le première étape que tu dois suivre immédiatement après avoir reçu une lettre de refus de visa ?', 'Envoyer un email de protestation à l''ambassade allemande', 'Lire attentivement la lettre de refus pour identifier le motif exact', 'Demander au consulat une nouvelle date d''entretien sans modification du dossier', 'Contacter un avocat spécialisé en droit de l''immigration', 1, 'Selon la leçon, la première étape correcte est de ''lire attentivement la lettre de refus'' qui ''indique le motif'' et constitue ''ta feuille de route pour corriger''.'),
  ('8-4-quoi-faire-en-cas-de-refus', 'module-8', 5, 'Quelle est la leçon principale que cette leçon veut que tu retiens maintenant que le recours gratuit a disparu ?', 'Qu''il faut toujours choisir le recours judiciaire car c''est l''option la plus sûre', 'Que tu dois attendre au moins 3 mois avant de redéposer une nouvelle demande', 'Que ton dossier doit être impeccable dès la première tentative pour éviter les coûts d''une seconde demande', 'Que le risque de refus a augmenté et qu''il faut absolument suivre une formation supplémentaire', 2, 'La leçon conclut que ''maintenant que le recours gratuit n''existe plus, ton dossier doit être impeccable DÈS la première tentative'' — c''est toute l''importance de cette formation.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('9-1-le-compte-bloque-sperrkonto', 'module-9', 1, 'Quel est l''objectif principal du compte bloqué (Sperrkonto) en Allemagne ?', 'Prouver aux autorités que tu peux subvenir à tes besoins pendant ton séjour en Allemagne', 'Ouvrir un compte courant auprès d''une banque allemande', 'Payer les frais de traitement de ta demande de visa', 'Payer les droits d''inscription à l''université allemande', 0, 'Le compte bloqué sert de preuve financière aux autorités allemandes que tu disposes de ressources pour vivre sur place pendant une année.'),
  ('9-1-le-compte-bloque-sperrkonto', 'module-9', 2, 'Pour quelle catégorie de personnes le compte bloqué est-il MOINS souvent obligatoire ?', 'Les demandeurs avec un visa de recherche d''emploi', 'Les personnes ayant un contrat de travail qualifié avec un salaire suffisant', 'Les candidats à la Chancenkarte', 'Les étudiants internationaux', 1, 'Selon la leçon, si tu as un contrat de travail avec un salaire suffisant (Ausbildung ou travail qualifié), tu n''as souvent PAS besoin de compte bloqué, car ton salaire fait la preuve de ta capacité financière.'),
  ('9-1-le-compte-bloque-sperrkonto', 'module-9', 3, 'Comment l''argent du compte bloqué est-il libéré une fois en Allemagne ?', 'Tu dois le demander à la banque chaque mois par courrier', 'Tu peux le retirer entièrement quand tu le souhaites', 'Il t''est versé automatiquement chaque mois selon une mensualité fixe', 'Les autorités le gardent jusqu''à la fin de tes études', 2, 'Le compte bloqué verse automatiquement une mensualité fixe chaque mois sur ton compte courant normal en Allemagne, tu ne peux pas retirer la totalité d''un coup.'),
  ('9-1-le-compte-bloque-sperrkonto', 'module-9', 4, 'Qu''est-ce que la Sperrbestätigung dans le processus du compte bloqué ?', 'C''est une lettre d''acceptation de l''université allemande', 'C''est le contrat d''emploi que tu dois signer en Allemagne', 'C''est une taxe prélevée par les autorités allemandes', 'C''est l''attestation de blocage que tu joins à ta demande de visa', 3, 'Tu reçois une Sperrbestätigung (attestation de blocage) du prestataire agréé, que tu dois joindre à ta demande de visa pour prouver le dépôt de fonds.'),
  ('9-1-le-compte-bloque-sperrkonto', 'module-9', 5, 'Vrai ou faux : l''argent du compte bloqué est une somme que tu perds définitivement ?', 'Faux, c''est TON argent que tu récupères mois après mois une fois en Allemagne', 'Faux, mais seulement si tu réussis tes études', 'Vrai, c''est comme une taxe payée aux autorités allemandes', 'Vrai, tu ne peux jamais le récupérer', 0, 'La leçon insiste sur le fait que le compte bloqué n''est PAS une perte : c''est ton propre argent qu''on te verse mensuellement, tout ce qui n''est pas utilisé te reste.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('9-2-combien-exactement-les-montants-2026', 'module-9', 1, 'Quel est le montant total en euros qu''un étudiant standard doit bloquer pour une année entière en Allemagne en 2026 ?', '12 000 euros', '10 920 euros', '11 904 euros', '13 092 euros', 2, 'La leçon indique explicitement que pour le cas standard (un étudiant, douze mois), le montant requis est de 11 904 euros pour l''année.'),
  ('9-2-combien-exactement-les-montants-2026', 'module-9', 2, 'Quel est le montant mensuel libéré chaque mois pour un demandeur détenteur de la Chancenkarte ?', '1 200 euros', '992 euros', '1 050 euros', '1 091 euros', 3, 'La leçon précise que pour la Chancenkarte, le montant annuel est de 13 092 euros, soit 1 091 euros libérés chaque mois.'),
  ('9-2-combien-exactement-les-montants-2026', 'module-9', 3, 'Pour quels types de visas faut-il ajouter une majoration de 10% au montant mensuel requis ?', 'Les visas pour reconnaître une qualification, un cours de langue, ou chercher une formation', 'Seulement les visas pour les familles', 'Tous les visas sans exception', 'Uniquement les visas pour employés qualifiés', 0, 'La leçon énumère précisément : « pour certains visas — notamment celui pour faire reconnaître une qualification, ou pour un cours de langue, ou pour chercher une formation — il faut majorer le montant mensuel de 10% ».'),
  ('9-2-combien-exactement-les-montants-2026', 'module-9', 4, 'Quel est le principal risque financier évoqué à propos des frais bancaires sur le compte bloqué ?', 'Les frais empêchent complètement l''accès aux fonds', 'Les frais, déduits du montant transféré, peuvent faire tomber le solde sous le minimum requis', 'Les frais doublent le montant total à transférer', 'Les frais sont illégaux en Allemagne', 1, 'La leçon avertit : « Si tu transfères EXACTEMENT 11 904 euros, ces frais sont déduits, et ton solde tombe en dessous du minimum requis. Résultat : refus. »'),
  ('9-2-combien-exactement-les-montants-2026', 'module-9', 5, 'Quelle marge de sécurité la leçon recommande-t-elle de transférer au lieu du montant exact pour le cas standard ?', '13 000 euros minimum', '11 904 à 12 000 euros', '12 000 à 12 100 euros', '12 100 à 12 200 euros', 2, 'La leçon conseille explicitement : « Pour le cas standard, vise dans les 12 000 à 12 100 euros plutôt que 11 904 pile, pour absorber les frais bancaires et de prestataire. »')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('9-3-comment-ouvrir-un-compte-bloque', 'module-9', 1, 'Quels sont les prestataires agréés spécialisés dans l''ouverture de compte bloqué pour visa mentionnés dans la leçon ?', 'Fintiba, Expatrio, et Coracle', 'Deutsche Bank, Commerzbank, et Sparkasse', 'PayPal, Stripe, et Square', 'Revolut, Wise, et N26', 0, 'La leçon mentionne explicitement Fintiba, Expatrio et Coracle comme les prestataires en ligne agréés et reconnus par les ambassades allemandes pour ouvrir un compte bloqué.'),
  ('9-3-comment-ouvrir-un-compte-bloque', 'module-9', 2, 'Quel délai est recommandé pour commencer la démarche d''ouverture de compte bloqué avant le rendez-vous de visa ?', 'Une semaine', 'Six à huit semaines', 'Trois mois', 'Deux à trois semaines', 1, 'La leçon insiste sur un timing crucial : commencer idéalement six à huit semaines avant le rendez-vous de visa pour permettre le transfert international, la vérification et l''émission de l''attestation.'),
  ('9-3-comment-ouvrir-un-compte-bloque', 'module-9', 3, 'Au moment de remplir le formulaire d''ouverture du compte bloqué, quel détail est important à bien sélectionner ?', 'Le domaine d''étude prévu', 'La banque française de correspondance', 'Le type de compte — étudiant ou Chancenkarte — pour que le montant requis soit correct', 'La date d''arrivée en Allemagne', 2, 'La leçon précise qu''il faut sélectionner le bon type — étudiant ou Chancenkarte — pour que le montant requis soit correct lors du remplissage du formulaire.'),
  ('9-3-comment-ouvrir-un-compte-bloque', 'module-9', 4, 'Après avoir reçu l''attestation de blocage (Sperrbestätigung), que doit-on en faire ?', 'L''envoyer uniquement à l''ambassade par courrier recommandé', 'La conserver jusqu''à l''obtention du passeport allemand', 'La garder secrète pour des raisons de sécurité', 'La joindre à la demande de visa', 3, 'La leçon indique clairement qu''il faut recevoir l''attestation de blocage et la joindre à sa demande de visa.'),
  ('9-3-comment-ouvrir-un-compte-bloque', 'module-9', 5, 'Une fois en Allemagne, quel document ou information supplémentaire doit-on fournir concernant le compte bloqué ?', 'L''IBAN du compte courant allemand pour recevoir les mensualités', 'Une attestation de résidence en Allemagne', 'La preuve d''emploi en Allemagne', 'Les reçus de toutes les transactions effectuées', 0, 'La leçon précise qu''une fois en Allemagne, il faudra fournir l''IBAN du compte courant allemand pour recevoir les mensualités du compte bloqué.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('9-4-les-alternatives-au-compte-bloque', 'module-9', 1, 'Selon la leçon, dans quel cas une attestation de bourse peut-elle remplacer le compte bloqué comme preuve de financement ?', 'Si la bourse est transférée directement sur un compte allemand avant l''arrivée', 'Seulement si la bourse vient d''un programme gouvernemental français', 'Si tu obtiens une bourse reconnue d''études ou d''un programme officiel', 'Uniquement pour les bourses d''un montant supérieur à 12 000 euros par an', 2, 'La leçon stipule que l''attestation d''une bourse reconnue (d''études ou d''un programme officiel) peut remplacer le compte bloqué, et c''est l''ambassade qui l''apprécie.'),
  ('9-4-les-alternatives-au-compte-bloque', 'module-9', 2, 'Quel est l''avantage principal des routes avec emploi (salaire) en termes de preuve financière ?', 'Elles permettent de transférer l''argent directement en Algérie sans frais', 'Elles garantissent une augmentation de salaire chaque année en Allemagne', 'Elles suppriment complètement l''obligation d''ouvrir un compte bloqué', 'La preuve financière est beaucoup plus légère ou souvent pas de compte bloqué', 3, 'La leçon indique clairement que les routes avec emploi ont l''avantage d''une preuve financière beaucoup plus légère, et souvent il n''y a pas de compte bloqué ou un montant réduit.'),
  ('9-4-les-alternatives-au-compte-bloque', 'module-9', 3, 'Pour la prise en charge par un garant, quelles conditions doit remplir cette personne selon la leçon ?', 'Elle doit avoir des revenus solides et démontrables dans la durée, et prouver son logement', 'Elle doit être citoyenne allemande depuis au moins 5 ans', 'Elle doit ouvrir un compte bloqué au nom du demandeur', 'Elle doit être un parent biologique et avoir un contrat de travail en CDI', 0, 'La leçon précise que le garant doit avoir des revenus solides et démontrables dans la durée, et s''engage formellement en prouvant ses revenus et son logement.'),
  ('9-4-les-alternatives-au-compte-bloque', 'module-9', 4, 'Si tu es étudiant sans bourse, quelle preuve financière te concerne selon le guide de la leçon ?', 'Une prise en charge par un garant', 'Un compte bloqué', 'Une attestation bancaire simplifiée', 'Un contrat de travail et un compte bloqué', 1, 'La leçon affirme explicitement que pour un étudiant sans bourse, c''est le compte bloqué qui s''applique.'),
  ('9-4-les-alternatives-au-compte-bloque', 'module-9', 5, 'Laquelle des affirmations suivantes au sujet des alternatives au compte bloqué est correcte selon la leçon ?', 'Le compte bloqué est obligatoire pour tous, même avec un bon salaire', 'La prise en charge par un garant s''applique surtout aux routes professionnelles', 'Un contrat de travail suffisant rend la preuve financière beaucoup plus légère', 'Les bourses algériennes sont systématiquement refusées par l''ambassade', 2, 'La leçon souligne que pour les routes avec emploi, le salaire suffisant prouve que tu peux vivre, rendant la preuve financière beaucoup plus légère ou supprimant le compte bloqué.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('10-1-la-declaration-de-domicile', 'module-10', 1, 'Quel est le délai légal dans lequel tu dois effectuer ton Anmeldung après ton emménagement en Allemagne ?', '14 jours', '30 jours', '3 jours', '7 jours', 0, 'La leçon précise clairement que le délai obligatoire est de 14 jours suivant l''emménagement.'),
  ('10-1-la-declaration-de-domicile', 'module-10', 2, 'Quel document signé par ton propriétaire ou logeur est indispensable pour faire ton Anmeldung ?', 'Le contrat de location suffit à lui seul', 'La Wohnungsgeberbestätigung', 'Une attestation de l''agence immobilière', 'Une copie de ta facture d''électricité', 1, 'La leçon souligne que la Wohnungsgeberbestätigung (confirmation signée du logeur) est indispensable, et que le contrat de location seul ne suffit généralement pas.'),
  ('10-1-la-declaration-de-domicile', 'module-10', 3, 'Que reçois-tu à la fin de ton rendez-vous à l''Anmeldung et pourquoi est-ce crucial ?', 'Un certificat d''imposition pour l''année en cours', 'Un reçu prouvant que tu as payé les frais d''enregistrement', 'La Meldebescheinigung ou Anmeldebestätigung, qui débloque l''accès aux services allemands', 'Une carte d''identité temporaire valable 6 mois', 2, 'La leçon explique que la Meldebescheinigung/Anmeldebestätigung est le document qui ouvre toutes les portes (compte bancaire, numéro fiscal, assurance santé, titre de séjour).'),
  ('10-1-la-declaration-de-domicile', 'module-10', 4, 'Quelle est la conséquence financière possible d''un retard dans ton Anmeldung ?', 'Une interdiction permanente de résider en Allemagne', 'Une obligation de payer des arriérés de loyer au Bürgeramt', 'Une amende jusqu''à 100 euros maximum', 'Une amende pouvant aller jusqu''à 1 000 euros dans les cas extrêmes', 3, 'La leçon indique qu''un retard peut entraîner une amende, pouvant atteindre jusqu''à 1 000 euros dans les cas extrêmes.'),
  ('10-1-la-declaration-de-domicile', 'module-10', 5, 'Pourquoi est-il important de prendre un rendez-vous au Bürgeramt rapidement, même si la date proposée est plus tardive que les 14 jours ?', 'Parce que l''email de confirmation de prise de rendez-vous prouve que tu as fait la démarche dans les temps', 'Parce que les frais d''inscription augmentent après 14 jours', 'Parce que tu risques sinon une amende immédiate sans possibilité d''appel', 'Parce que les rendez-vous se remplissent très vite et il faut éviter de devoir revenir plus tard', 0, 'La leçon explique qu''en cas de difficulté à obtenir un rendez-vous dans les 14 jours, l''email de confirmation prouve que tu as fait la démarche en temps voulu, ce qui te protège.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('10-2-le-titre-de-sejour-l-assurance-sante', 'module-10', 1, 'À quel moment après ton arrivée en Allemagne dois-tu demander ton titre de séjour auprès de l''Ausländerbehörde ?', 'Avant d''arriver en Allemagne', 'Dans les 30 premiers jours', 'Généralement dans les 90 premiers jours', 'Dans les 6 premiers mois', 2, 'La leçon précise que tu dois demander le titre de séjour ''généralement dans les 90 premiers jours'' de ton séjour.'),
  ('10-2-le-titre-de-sejour-l-assurance-sante', 'module-10', 2, 'Pourquoi l''assurance santé est-elle essentielle dans la procédure d''installation en Allemagne ?', 'Elle couvre uniquement le salarié, pas sa famille', 'Elle est nécessaire uniquement pour les étudiants', 'Elle te permet d''obtenir gratuitement les médicaments', 'Sans elle, tu ne peux pas obtenir ton titre de séjour, car elle est obligatoire', 3, 'La leçon affirme explicitement : ''En Allemagne, l''assurance santé est OBLIGATOIRE — sans elle, pas de titre de séjour, c''est non négociable.'''),
  ('10-2-le-titre-de-sejour-l-assurance-sante', 'module-10', 3, 'Quel document provisoire te couvre légalement si ton visa d''entrée expire avant que ton titre de séjour soit prêt ?', 'La Fiktionsbescheinigung', 'L''Ausländerbehörde temporaire', 'La Anmeldebestätigung', 'Le Girokonto', 0, 'La leçon mentionne que si ton visa expire avant ton titre : ''on te délivre un document provisoire, la Fiktionsbescheinigung, qui te couvre légalement en attendant.'''),
  ('10-2-le-titre-de-sejour-l-assurance-sante', 'module-10', 4, 'Quel est l''ordre logique correct des démarches administratives selon la leçon ?', 'Assurance santé, puis Anmeldung, puis titre de séjour', 'Anmeldung d''abord, puis assurance santé et compte bancaire, puis dépôt du titre de séjour', 'Titre de séjour, puis Anmeldung, puis assurance santé', 'Compte bancaire, puis assurance santé, puis Anmeldung', 1, 'La leçon explique : ''Anmeldung d''abord, parce qu''elle débloque tout. Puis assurance santé et compte bancaire, qui sont nécessaires au titre de séjour. Puis dépôt du titre de séjour.'''),
  ('10-2-le-titre-de-sejour-l-assurance-sante', 'module-10', 5, 'Pour ouvrir un Girokonto (compte bancaire courant) en Allemagne, quels documents te sont généralement nécessaires ?', 'Ton visa d''entrée et une lettre d''emploi', 'Ton passeport et une preuve d''assurance santé', 'Ton passeport et l''Anmeldebestätigung (attestation de domicile)', 'Ton titre de séjour et une preuve de revenus', 2, 'La leçon indique : ''Pour l''ouvrir, il te faut généralement ton passeport et ton attestation de domicile, l''Anmeldebestätigung.''')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('10-3-compte-bancaire-carte-sim', 'module-10', 1, 'Quel document est nécessaire pour ouvrir un compte bancaire courant (Girokonto) en Allemagne ?', 'Le passeport et l''attestation de domicile (Anmeldebestätigung)', 'Le passeport et une lettre d''employeur', 'Le passeport, l''Anmeldebestätigung et une vérification de solvabilité', 'Uniquement le passeport', 0, 'La leçon indique qu''il faut généralement le passeport et l''attestation de domicile (Anmeldebestätigung) pour ouvrir un Girokonto.'),
  ('10-3-compte-bancaire-carte-sim', 'module-10', 2, 'Pourquoi la leçon recommande-t-elle de choisir une banque en ligne pour démarrer ?', 'Parce qu''elle est obligatoire par la loi allemande', 'Parce qu''elle est plus rapide à ouvrir, gérée par téléphone, et disponible en anglais', 'Parce qu''elle offre des taux d''intérêt plus élevés que les banques traditionnelles', 'Parce qu''elle ne demande pas de passeport pour l''ouverture', 1, 'La leçon souligne que les banques en ligne sont souvent plus rapides à ouvrir, gérables depuis le téléphone, et disponibles en anglais, ce qui est pratique au début.'),
  ('10-3-compte-bancaire-carte-sim', 'module-10', 3, 'Quels documents suffit-il d''avoir pour acheter une carte SIM prépayée lors de l''arrivée en Allemagne ?', 'Passeport et compte bancaire allemand', 'Passeport et Anmeldebestätigung', 'Passeport et adresse temporaire (hôtel ou logement d''arrivée)', 'Passeport et vérification de solvabilité', 2, 'La leçon explique qu''une carte SIM prépayée ne demande que le passeport et une adresse temporaire ; l''Anmeldung n''est pas nécessaire.'),
  ('10-3-compte-bancaire-carte-sim', 'module-10', 4, 'Quel est l''avantage principal d''une carte SIM prépayée comparée à un forfait avec engagement ?', 'Elle est plus économique à long terme', 'Elle permet d''accéder à davantage de pays', 'Elle offre un meilleur réseau de couverture', 'Elle peut être activée immédiatement à l''arrivée sans Anmeldung ni compte bancaire', 3, 'La leçon précise que le forfait avec engagement demande l''Anmeldung, un compte bancaire allemand et une vérification de solvabilité, alors que la carte prépayée peut être activée dès l''arrivée avec juste le passeport.'),
  ('10-3-compte-bancaire-carte-sim', 'module-10', 5, 'Dans quel ordre logique faut-il configurer ces éléments selon la leçon ?', 'Carte SIM prépayée d''abord, puis Anmeldung, puis compte bancaire et forfait plus tard', 'Compte bancaire, puis Anmeldung, puis carte SIM', 'Forfait téléphone d''abord, puis compte bancaire, puis Anmeldung', 'Forfait téléphone, puis Anmeldung, puis compte bancaire', 0, 'La leçon établit clairement que la SIM prépayée doit venir en premier (dès l''arrivée), ensuite l''Anmeldung et le compte bancaire, et enfin le forfait une fois qu''on est installé.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('10-4-la-checklist-de-survie-des-30', 'module-10', 1, 'Dans quels délais devez-vous effectuer votre Anmeldung (enregistrement auprès de la mairie) après votre arrivée en Allemagne ?', 'Dans les 90 jours', 'Dans les 7 jours', 'Idéalement dans les 14 jours', 'Dans les 30 jours', 2, 'La leçon stipule clairement que l''Anmeldung doit être faite « idéalement dans les 14 jours », bien qu''il soit recommandé de prendre rendez-vous immédiatement au Bürgeramt.'),
  ('10-4-la-checklist-de-survie-des-30', 'module-10', 2, 'Quel document officiel reçu après votre Anmeldung est décrit comme « la clé qui ouvre tout le reste » ?', 'La Fiktionsbescheinigung', 'La Steuer-ID', 'La Wohnungsgeberbestätigung', 'La Meldebescheinigung', 3, 'La leçon dit explicitement de « récupérer et garder précieusement ton attestation, la Meldebescheinigung. C''est la clé qui ouvre tout le reste ».'),
  ('10-4-la-checklist-de-survie-des-30', 'module-10', 3, 'Combien de temps après votre Anmeldung recevez-vous généralement votre numéro fiscal (Steuer-ID) par courrier ?', 'Deux à quatre semaines', 'Quatre à six semaines', 'Une à deux semaines', 'Deux à trois semaines', 0, 'La leçon indique que le numéro fiscal « arrive automatiquement sous deux à quatre semaines après l''Anmeldung ».'),
  ('10-4-la-checklist-de-survie-des-30', 'module-10', 4, 'Quel est le montant approximatif de la redevance audiovisuelle (Rundfunkbeitrag) à payer mensuellement par foyer en Allemagne ?', 'Environ 12 euros', 'Environ 18 euros', 'Environ 25 euros', 'Environ 30 euros', 1, 'La leçon précise que le Rundfunkbeitrag est « environ dix-huit euros par mois et par foyer ».'),
  ('10-4-la-checklist-de-survie-des-30', 'module-10', 5, 'Quel document provisoire vous est délivré si votre visa expire avant la décision du titre de séjour ?', 'Une Meldebescheinigung prolongée', 'Une Wohnungsgeberbestätigung temporaire', 'Une Fiktionsbescheinigung', 'Une attestation d''Anmeldung valide', 2, 'La leçon affirme que « si ton visa expire avant la décision, on te délivre un document provisoire, la Fiktionsbescheinigung, qui te couvre ».')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('n-0-trouve-ton-metier-sur-la-liste', 'niches', 1, 'Qu''est-ce qu''un métier en tension (Engpassberufe) selon la leçon ?', 'Un métier où la demande des employeurs dépasse largement le nombre de candidats qualifiés disponibles.', 'Un métier qui existe uniquement dans les régions rurales allemandes.', 'Un métier qui n''accepte que les résidents allemands établis.', 'Un métier qui nécessite une formation très longue en Allemagne.', 0, 'La leçon définit explicitement un métier en tension comme un métier où la demande des employeurs dépasse largement le nombre de candidats qualifiés disponibles.'),
  ('n-0-trouve-ton-metier-sur-la-liste', 'niches', 2, 'Combien de professions environ sont classées en pénurie selon la leçon ?', '100 professions', '163 professions', '200 professions', '50 professions', 1, 'La leçon mentionne explicitement qu''on parle d''environ 163 professions classées en pénurie selon l''Agence fédérale pour l''emploi.'),
  ('n-0-trouve-ton-metier-sur-la-liste', 'niches', 3, 'Parmi les trois avantages réels d''exercer un métier en tension, lequel n''est PAS mentionné dans la leçon ?', 'Un seuil de salaire réduit pour la Blue Card.', 'Une procédure accélérée grâce à la levée de la vérification de priorité du marché.', 'Une exonération complète des impôts sur le revenu pendant 5 ans.', 'Des points supplémentaires pour la Chancenkarte (Carte opportunité).', 2, 'La leçon énumère trois avantages : seuil de salaire réduit, procédure accélérée, et points bonus pour la Chancenkarte. L''exonération fiscale n''est jamais mentionnée.'),
  ('n-0-trouve-ton-metier-sur-la-liste', 'niches', 4, 'Comment la procédure peut-elle être accélérée pour un métier en tension ?', 'En obtenant directement la nationalité allemande sans délai.', 'En contournant complètement la procédure de visa.', 'En payant une taxe administrative supplémentaire.', 'Parce que la vérification de priorité du marché est souvent levée, ce qui peut faire passer le dossier de plusieurs mois à quelques semaines.', 3, 'La leçon explique que la vérification de priorité du marché est souvent levée pour les métiers en tension, ce qui peut transformer un délai de plusieurs mois en quelques semaines.'),
  ('n-0-trouve-ton-metier-sur-la-liste', 'niches', 5, 'Quels sont les deux outils officiels recommandés pour vérifier si ton métier figure sur la liste ?', 'La liste des métiers en tension publiée par l''Agence fédérale et le portail Make it in Germany.', 'Uniquement la base Anabin et des forums communautaires.', 'LinkedIn et Indeed.', 'La base Anabin et le site de l''Agence fédérale pour l''emploi.', 0, 'La leçon mentionne explicitement deux outils officiels : la liste des métiers en tension de l''Agence fédérale et le portail Make it in Germany pour vérifier les professions recherchées.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('niche-1-sante-pflege-medical', 'niches', 1, 'Combien de postes vacants environ sont disponibles dans le secteur de la santé en Allemagne selon la leçon ?', 'Environ 100 000 postes', 'Environ 20 000 postes', 'Environ 46 000 postes', 'Environ 65 000 postes', 2, 'La leçon mentionne explicitement « environ 46 000 » postes vacants dans la santé, catégorie en tête de toutes les tensions.'),
  ('niche-1-sante-pflege-medical', 'niches', 2, 'Quel est le principal avantage de la Blue Card pour les professionnels de santé étrangers ?', 'Elle autorise automatiquement la résidence permanente', 'Elle dispense de l''examen de langue médicale spécialisée', 'Elle permet de travailler sans reconnaissance du diplôme', 'Elle a un seuil de salaire réduit et lève souvent la vérification de priorité du marché', 3, 'La leçon stipule que les professionnels de santé bénéficient d''un seuil de salaire réduit pour la Blue Card et que la vérification de priorité du marché est souvent levée, ce qui accélère le dossier.'),
  ('niche-1-sante-pflege-medical', 'niches', 3, 'Pourquoi l''Anerkennung (reconnaissance du diplôme) est-elle obligatoire dans le secteur de la santé ?', 'Parce que la santé est un métier réglementé', 'Parce que l''Allemagne ne reconnaît pas les diplômes étrangers', 'Parce que c''est une condition du visa d''étudiant', 'Parce que les infirmiers doivent passer obligatoirement deux années supplémentaires', 0, 'La leçon affirme clairement que « la santé est un métier RÉGLEMENTÉ » et que « la reconnaissance de ton diplôme — l''Anerkennung — est OBLIGATOIRE ».'),
  ('niche-1-sante-pflege-medical', 'niches', 4, 'Quel nouveau dispositif permet aux candidats de commencer à travailler pendant la reconnaissance du diplôme ?', 'Le stage obligatoire de deux ans', 'Le partenariat de reconnaissance, souvent en tant qu''aide-soignant (Pflegehilfskraft)', 'La certification rapide accordée par l''État fédéral', 'Le travail au pair dans les hôpitaux', 1, 'La leçon indique que grâce au partenariat de reconnaissance, on peut entrer et commencer à travailler « souvent comme aide-soignant, Pflegehilfskraft — pendant que tu finalises ta reconnaissance sur place ».'),
  ('niche-1-sante-pflege-medical', 'niches', 5, 'Quel examen de langue spécialisée est recommandé pour les professionnels de santé en Allemagne ?', 'Le Goethe B2 général sans spécialisation', 'Le DSH pour tous les secteurs d''activité', 'Le telc B2 Pflege pour l''allemand médical', 'Le TOEFL en allemand', 2, 'La leçon précise qu''un examen de langue spécialisé médical (Fachsprachprüfung Pflege) est nécessaire et mentionne que « le telc B2 Pflege est exactement conçu pour ça ».')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('niche-2-it-informatique', 'niches', 1, 'Quel est l''avantage UNIQUE de la niche IT en Allemagne par rapport à d''autres secteurs ?', 'On peut obtenir une Blue Card SANS diplôme universitaire si on a 3 ans d''expérience pertinente.', 'Les entreprises payent intégralement les cours de langue allemande.', 'L''accès au marché du travail est garanti dans les 6 mois.', 'Les salaires sont 50% plus élevés qu''ailleurs.', 0, 'La leçon indique explicitement que l''IT est l''unique secteur où tu peux obtenir une Blue Card sans diplôme universitaire avec 3 ans d''expérience professionnelle pertinente au cours des 7 dernières années.'),
  ('niche-2-it-informatique', 'niches', 2, 'Selon la leçon, pourquoi l''Allemagne représente-t-elle une opportunité majeure pour les professionnels IT ?', 'C''est le seul pays d''Europe qui embauche sans parlé l''allemand.', 'L''Allemagne a une des plus fortes pénuries de talents IT d''Europe, avec des centaines de milliers de postes non pourvus.', 'Les entreprises allemandes offrent automatiquement la nationalité après 2 ans.', 'L''Allemagne impose un salaire minimum unique pour tous les développeurs.', 1, 'La leçon mentionne explicitement que l''Allemagne a une des pénuries de talents IT les plus fortes d''Europe, avec des centaines de milliers de postes non pourvus dans des domaines comme le développement, l''architecture système, la data et la cybersécurité.'),
  ('niche-2-it-informatique', 'niches', 3, 'Quelle condition importante s''ajoute au traitement de la Blue Card sans diplôme en IT ?', 'Un examen technique passé devant un jury allemand.', 'Une certification en ligne obligatoire de 3 mois.', 'L''Agence fédérale pour l''emploi doit valider le cas, ce qui ajoute quelques semaines au traitement.', 'Une maîtrise obligatoire de l''allemand niveau B1.', 2, 'La leçon précise que pour la route sans diplôme, l''Agence fédérale pour l''emploi doit valider le cas, ce qui ajoute quelques semaines au traitement du dossier.'),
  ('niche-2-it-informatique', 'niches', 4, 'Dans quels contextes professionnels l''anglais peut-il suffire en IT allemande ?', 'Uniquement pour les freelances travaillant à distance depuis l''étranger.', 'Dans les universités allemandes uniquement.', 'Uniquement dans les très petites start-ups de moins de 20 personnes.', 'Dans beaucoup d''entreprises tech, surtout à Berlin et Munich et dans les multinationales.', 3, 'La leçon indique que dans beaucoup d''entreprises tech, surtout à Berlin et Munich et dans les multinationales, on travaille en anglais et que l''allemand n''est pas toujours exigé au départ.'),
  ('niche-2-it-informatique', 'niches', 5, 'Comment est classé l''IT au regard de la réglementation professionnelle en Allemagne ?', 'C''est un métier NON réglementé où l''expérience et les compétences priment, bien que la vérification sur anabin soit recommandée.', 'C''est un métier semi-réglementé avec obligation de diplôme minimum.', 'C''est un métier sans reconnaissance officielle en Allemagne.', 'C''est un métier strictement réglementé nécessitant une licence d''État.', 0, 'La leçon affirme que l''IT est généralement un métier NON réglementé où la reconnaissance formelle du diplôme n''est pas toujours obligatoire, et que l''expérience et les compétences priment.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('niche-3-ingenierie', 'niches', 1, 'Quel cluster professionnel regroupe l''ingénierie avec d''autres domaines en forte demande en Allemagne ?', 'Le cluster des métiers manuels et techniques (MMT)', 'Le cluster de la construction et du bâtiment (CB)', 'Le cluster STEM (sciences, technologie, ingénierie, mathématiques)', 'Le cluster énergétique et industriel (EI)', 2, 'La leçon spécifie explicitement que l''ingénierie fait partie du cluster STEM, au cœur des métiers en tension.'),
  ('niche-3-ingenierie', 'niches', 2, 'Quel type de visa est présenté comme "l''autoroute" pour les ingénieurs qualifiés ayant une offre d''emploi en Allemagne ?', 'Le visa touristique avec extension emploi', 'La carte de résident permanent directe', 'La Chancenkarte pour chercher sur place', 'La Blue Card avec seuil de salaire réduit pour les métiers en tension', 3, 'La leçon affirme que la Blue Card est ''ton autoroute, avec le seuil de salaire réduit des métiers en tension'' pour les ingénieurs ayant une offre et un diplôme reconnu.'),
  ('niche-3-ingenierie', 'niches', 3, 'Parmi les domaines d''ingénierie suivants, lequel est explicitement mentionné comme lié à la transition énergétique en Allemagne ?', 'L''ingénierie solaire, éolienne et efficacité énergétique', 'L''ingénierie aéronautique et spatiale', 'L''ingénierie textile et manufacturière', 'L''ingénierie chimique et pharmaceutique', 0, 'La leçon mentionne explicitement ''solaire, éolien, efficacité énergétique, bâtiment durable'' comme domaines liés à la transition énergétique avec forte demande.'),
  ('niche-3-ingenierie', 'niches', 4, 'Quel est le niveau d''allemand recommandé pour maximiser les options d''emploi en ingénierie en Allemagne ?', 'Un A2 suffisant pour communiquer en entreprise', 'Un B1 solide, même si l''anglais est possible dans certaines grandes entreprises', 'Un C1 obligatoire pour tous les postes d''ingénieur', 'Aucun niveau spécifique, l''anglais remplace partout l''allemand', 1, 'La leçon stipule ''Vise au moins un B1 solide pour maximiser tes options'', tout en reconnaissant que l''anglais est possible dans les grands groupes mais que B1-B2 est attendu pour beaucoup de postes.'),
  ('niche-3-ingenierie', 'niches', 5, 'Avant de candidater, quelle est l''étape importante recommandée pour vérifier la reconnaissance de son diplôme d''ingénieur ?', 'Consulter uniquement le curriculum des universités allemandes', 'Demander directement à l''entreprise si elle accepte le diplôme', 'Faire vérifier le diplôme sur Anabin et lancer la reconnaissance si la branche l''exige', 'Redoubler tous les cours en Allemagne avant de postuler', 2, 'La leçon précise : ''fais vérifier ton diplôme sur anabin, et lance la reconnaissance si ta branche l''exige'' pour rassurer l''employeur et fluidifier le visa.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('niche-4-metiers-techniques-electricien', 'niches', 1, 'Quel problème démographique affecte actuellement les métiers techniques en Allemagne ?', 'Un trou générationnel : des ouvriers qualifiés qui partent à la retraite sans assez de jeunes pour les remplacer', 'Une interdiction gouvernementale de former de nouveaux électriciens', 'Une préférence systématique pour les diplômés universitaires dans tous les secteurs', 'Une surpopulation de jeunes ouvriers sans emploi', 0, 'La leçon décrit explicitement un trou générationnel où une génération d''ouvriers qualifiés part à la retraite sans assez de jeunes pour les remplacer.'),
  ('niche-4-metiers-techniques-electricien', 'niches', 2, 'Si tu as déjà une qualification professionnelle reconnue, quelle est la route la plus appropriée pour travailler en Allemagne dans les métiers techniques ?', 'L''Ausbildung (apprentissage rémunéré)', 'Le visa de travailleur qualifié', 'Un visa touristique convertible en permis de travail', 'Aucun visa n''est nécessaire si tu as une qualification', 1, 'La leçon stipule que si tu as déjà une qualification professionnelle, le visa de travailleur qualifié est la route appropriée, car la qualification professionnelle (pas seulement universitaire) ouvre cette porte.'),
  ('niche-4-metiers-techniques-electricien', 'niches', 3, 'Quel niveau de langue allemande est généralement attendu pour les métiers techniques en Allemagne ?', 'A2 (niveau élémentaire)', 'C1 (niveau opérationnel efficace)', 'B1-B2 (niveau intermédiaire supérieur)', 'Aucun niveau minimal n''est exigé', 2, 'La leçon précise clairement qu''un niveau B1-B2 en allemand est généralement attendu pour ces métiers, car la sécurité au travail et la communication d''équipe l''exigent.'),
  ('niche-4-metiers-techniques-electricien', 'niches', 4, 'Parmi les métiers mentionnés dans cette leçon, lesquels sont touchés par la pénurie de main-d''œuvre qualifiée ?', 'Seulement les électriciens et les mécaniciens industriels', 'Tous les métiers sans exception en Allemagne', 'Électriciens, mécatroniciens et techniciens en chauffage-ventilation-climatisation uniquement', 'Électriciens, mécatroniciens, mécaniciens industriels et techniciens en chauffage-ventilation-climatisation', 3, 'La leçon énumère explicitement comme touchés par la pénurie les mécatroniciens, électriciens, mécaniciens industriels et techniciens en chauffage-ventilation-climatisation.'),
  ('niche-4-metiers-techniques-electricien', 'niches', 5, 'Selon la leçon, où peux-tu chercher des offres d''emploi pour les métiers techniques en Allemagne ?', 'La Jobbörse de l''Agence fédérale, les chambres des métiers, les PME du Mittelstand et le contact direct avec les entreprises', 'Dans les agences de travail temporaire exclusivement', 'Sur les réseaux sociaux uniquement, car les entreprises ne publient pas d''annonces officielles', 'Uniquement auprès de grandes entreprises internationales', 0, 'La leçon indique précisément que tu peux chercher via la Jobbörse de l''Agence fédérale, les chambres des métiers, les PME du Mittelstand et le contact direct avec les entreprises de ta spécialité.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('niche-5-batiment-construction', 'niches', 1, 'Quel est le principal problème que les entreprises de construction en Allemagne signalent actuellement ?', 'Un manque d''outils et d''équipement moderne', 'Un manque de diplômés universitaires en ingénierie', 'Une pénurie de main-d''œuvre qualifiée', 'Une baisse importante de la demande de services de construction', 2, 'La leçon indique que la construction affiche l''un des taux de pénurie les plus élevés du pays, avec de nombreuses entreprises déclarant manquer de main-d''œuvre qualifiée.'),
  ('niche-5-batiment-construction', 'niches', 2, 'Parmi les deux voies principales mentionnées pour travailler dans le bâtiment en Allemagne, laquelle est décrite comme particulièrement accessible pour les candidats sans diplôme universitaire ?', 'Un master en génie civil obtenu à l''étranger', 'Un diplôme de management de projet', 'Le doctorat en architecture', 'L''Ausbildung, pour apprendre et se qualifier dans le système allemand', 3, 'La leçon précise que le bâtiment recrute via des qualifications professionnelles, pas seulement des diplômes universitaires, et cite l''Ausbildung comme une route accessible pour se qualifier.'),
  ('niche-5-batiment-construction', 'niches', 3, 'Quel niveau d''allemand est généralement attendu pour travailler en sécurité sur un chantier ?', 'B1, voire B2', 'C1 minimum obligatoire', 'Aucun niveau spécifique n''est requis', 'A1 ou A2', 0, 'La leçon stipule qu''un allemand B1, voire B2, est généralement attendu pour la sécurité sur chantier et la coordination d''équipe, car la communication peut être une question de sécurité.'),
  ('niche-5-batiment-construction', 'niches', 4, 'Selon la leçon, pour quels candidats la reconnaissance de qualification professionnelle est-elle particulièrement importante dans le secteur du bâtiment ?', 'Uniquement pour les femmes', 'Pour ceux exerçant en indépendant et dans certains métiers réglementés', 'Pour tous les candidats sans exception', 'Pour les candidats ayant moins de 25 ans', 1, 'La leçon indique que certains métiers réglementés du bâtiment, surtout en indépendant, exigent des certificats de compétence, rendant la reconnaissance particulièrement importante dans ces contextes.'),
  ('niche-5-batiment-construction', 'niches', 5, 'Quelle approche de recherche d''emploi la leçon décrit-elle comme particulièrement efficace dans le secteur de la construction ?', 'Attendre une offre d''emploi en ligne sans prendre l''initiative', 'Ne postuler qu''aux grandes entreprises multinationales', 'La candidature spontanée auprès d''entreprises locales', 'Utiliser exclusivement des agences de recrutement payantes', 2, 'La leçon affirme que la demande est telle que la candidature spontanée auprès d''entreprises locales est très efficace pour trouver un emploi dans le bâtiment.')
INSERT INTO public.immigration_quiz_questions
  (lesson_slug, module_slug, position, question_text, option_a, option_b, option_c, option_d, correct_index, explanation)
VALUES
  ('niche-6-transport-logistique', 'niches', 1, 'Selon la leçon, quel est le taux de pénurie de personnel dans le secteur du transport et de la logistique en Allemagne ?', 'Environ trois entreprises sur dix déclarent manquer de personnel', 'Environ une entreprise sur deux déclare manquer de personnel', 'Quatre entreprises sur dix déclarent manquer de personnel', 'Une entreprise sur cinq déclare manquer de personnel', 0, 'Le script indique explicitement : ''trois entreprises sur dix déclarent manquer de personnel''.'),
  ('niche-6-transport-logistique', 'niches', 2, 'Quelles sont les deux routes principales pour immigrer en Allemagne dans le secteur de la logistique ?', 'Le visa visiteur ou le contrat de travail non qualifié', 'Le visa de travailleur qualifié ou l''Ausbildung', 'La Jobbörse ou le contact direct avec les transporteurs', 'La Blue Card ou l''immigration familiale', 1, 'La leçon précise : ''le visa de travailleur qualifié si tu as une qualification reconnue, ou l''Ausbildung pour les métiers logistiques qualifiés''.'),
  ('niche-6-transport-logistique', 'niches', 3, 'Quel niveau d''allemand est généralement le minimum requis pour travailler dans le transport et la logistique ?', 'Un niveau A2 pour la communication de base', 'Un niveau C1 pour une maîtrise complète', 'Un niveau B1 pour la coordination et la sécurité', 'Un niveau B2 obligatoire pour tous les rôles', 2, 'Le script affirme : ''un allemand B1 est généralement le minimum, pour la coordination, la sécurité et les échanges''.'),
  ('niche-6-transport-logistique', 'niches', 4, 'Quel type de certification professionnelle nécessite une attention particulière dans le secteur logistique selon la leçon ?', 'Les certificats de langues étrangères', 'Les brevets de sécurité générale', 'Les diplômes universitaires en gestion', 'Les permis de conduire professionnels et certificats de qualification conducteur', 3, 'La leçon souligne : ''attention aux certifications professionnelles spécifiques — permis poids lourd, certificats de qualification conducteur. Elles peuvent nécessiter une reconnaissance''.'),
  ('niche-6-transport-logistique', 'niches', 5, 'Où la leçon conseille-t-elle de chercher un emploi dans le transport et la logistique ?', 'La Jobbörse, les grandes entreprises de logistique, les plateformes spécialisées et le contact direct avec les entrepôts', 'Seulement par agences de recrutement internationales', 'Via les services consulaires algériens uniquement', 'Uniquement via les universités allemandes', 0, 'Le script énumère : ''la Jobbörse, les grandes entreprises de logistique et de transport, les plateformes spécialisées du secteur, et le contact direct avec les entrepôts et transporteurs''.')
